('Александр Маршал',
'https://afisha.yandex.ru/samara/concert/aleksandr-marshal-tour?source=rubric',
'Многие знают всем полюбившиеся хиты музыканта, такие как — «Белый пепел», «Ливень», «Орёл», «Погоди, постой», «Отпускаю», «Невеста» и многие, многие другие. Известный российский рок-музыкант, автор и исполнитель песен, он давно и по праву пользуется популярностью у широкой аудитории. И это неудивительно, ведь музыка Александра Маршала всегда мелодична и эмоциональна, а песни глубоко лиричны и полны искренней любви к родной стране и её людям. Своим творчеством музыкант неизменно вдохновляет слушателей и мотивирует их на то, чтобы занимать в жизни активную человеческую, гражданскую позицию, а не оставаться просто сторонними наблюдателями.

«Мы вернёмся домой!» — название концерта, актуально как никогда в наше время, так как особое внимание артист уделяет военно-патриотической теме. Именно ей посвящены семь его альбомов: «Горец», «Особый», «Батя», «Летят журавли», «Отец Арсений», «Или так», «До свидания, полк».

В программе также будут исполнены несколько хитов из наследия Gorky Park (Парк Горького), которая в своё время занимала строчки в Billboard 100 и 200, MTV Chart и была самой популярной рок-группой из СССР за рубежом.',
'от 1 800 ₽',
'https://avatars.mds.yandex.net/get-afishanew/4768735/a50dfd973a711486741a24b8f0ad3517/s760x440',
2024437855227088517,
'2025-06-02 19:00:00',
5),
('Зара',
'https://afisha.yandex.ru/samara/concert/zara-2025-05?source=rubric',
'Творчество Зары пропитано любовью к жизни. Песни, задевающие самые тонкие струны души, горячо любимы слушателями.

Именно такая музыка наполняет верой, надеждой, объединяет людей разных возрастов и национальностей.

В репертуаре артистки: романсы, зажигательные и популярные эстрадные хиты. На сцене прозвучат этнические композиции с их богатой историей и культурой.

Зара сочетает в себе восточный и русский мир. Понимание разных музыкальных традиций позволяет особенным образом пропускать через себя исполняемые лирические композиции.

Зара является лауреатом премий «Муз-ТВ», «RU-TV», «Золотой граммофон», «Песня года» и многих других. Вместе со своим музыкальным бэндом Зара ждёт вас!',
'от 2 000 ₽',
