('Чайф',
'https://afisha.yandex.ru/samara/concert/chaif-40-let-tour?source=rubric',
'«Чайфу» — 40. Эта круглая цифра вмещает большую историю, победы и преодоления, много тысяч километров дорог, сотни песен и огромную любовь поклонников.

Юбилейный концерт к 40-летию — своего рода отчёт. Конечно, в его программу войдут ваши самые любимые и самые известные песни «Чайфа». Концерт уже вошёл в историю группы, его ждут как музыканты, так, уверены, и поклонники. Он, безусловно, станет событием российской музыки.

Главная цель каждого концерта «Чайфа» — удовольствие поклонников. Группа умеет сделать так, чтобы даже случайный зритель, зашедший послушать три известные ему песни, ушёл из зала в хорошем настроении.

Большой юбилейный концерт — это возможность для «Чайфа» показать, что в свои 40 лет группа по-прежнему в отличной концертной форме, и её выступления — традиционная радость и восторг для любителей хорошей музыки.

«Чайфу» — 40. Эта круглая цифра вмещает гораздо больше, чем любой рассказ о группе. И гораздо лучше об этой дате может сказать юбилейный концерт «Чайфа».',
