('Нейромонах Феофан',
'https://afisha.yandex.ru/samara/concert/neiromonakh-feofan-tour?source=rubric',
'Нейромонах Феофан отмечает 15-летие проекта туром по стране: всё, чем полюбился вам Драм Древнерусский за эти годы, воплотится в единой концертной программе!

Гостей ждёт не только сет-лист из самых популярных треков, но и новый материал; а шоу вберёт в себя весь лучший опыт, реализованный проектом за годы работы, — большая привычная всем концертная программа, для которой будут записаны и хор, и живые инструменты, в том числе электрогитара; добавится и акустическое звучание, и элементы программы «‎Симбиоз»! Не обойдётся и без традиционных забав: будут хороводы (а для красных девиц — персональный), будут балагурить под «Дурь», нарядными сарафанами да рубахами хвастаться, ну и конечно, каждый сможет «Притоптать».

Никто не знает, как Нейромонах Феофан выглядит на самом деле: на концертах солист проекта прячет лицо под капюшоном, из-под которого торчит только густая борода. Сопровождают драмодея неизменно диджей Никодим да медведь косолапый.

Уникальный проект, с самобытным и узнаваемым звучанием, сочетающим энергичный Drum&amp;Bass, мелодичность русских народных мотивов и красивый глубокий вокал — это Нейромонах Феофан. Сказавший новое слово в музыке и привлёкший внимание широкой аудитории, он получил отклик в сердцах и любителей электронной музыки, и закоренелых фанатов рока, и брутальных гиков, и маленьких даже детей, и продолжает делать это на протяжении всех 15 лет.

Четыре совершенно разных альбома, серия из мини-альбомов, несколько EP, Live-альбомов и синглов; сотни миллионов прослушиваний и просмотров на стримингах и видео-хостингах; концерты на крупнейших площадках страны и за её пределами; оглушительный успех на фестивалях от рок- до кибер-тематики и полное единодушие со слушателями — всё это популярность древнерусского Драма.

Станьте частью истории Драма Древнерусского, отметьте 15-летие проекта лихими плясками!',
