('Тропик-шоу',
'https://afisha.yandex.ru/samara/circus_show/tropik-shou-rosgostsirk?source=rubric',
'Самое летнее приключение!

Путешествие в тропики! Тропики в цирке!

Затаив дыхание, отправляемся в долгожданное путешествие под руководством заслуженного артиста России Тиграна Акопяна!

Это не просто представление, а шоу и яркий спектакль. Атмосфера жарких тропиков и погружение в добрый и сказочный мир цирка. Акробатика, эквилибр, контактная дрессура. Путешествие под названием «Тропик шоу».

В программе принимают участие: Легендарный аттракцион «Джамбо» под руководством Залуженного артиста России Тиграна Акопяна. Звезда манежа — бегемот Юлиана. Эти животные не поддаются дрессировке, но любовь и долгие тренировки творят чудеса. Одно из самых редких животных в цирке уже готово удивлять зрителя!

Всего в программе более 50 животных: верблюды, обезьяны, крокодилы, удавы, ламы, пони. Все обитатели жарких тропиков на одном манеже!

Также удивлять гостей будут:
— Воздушные гимнасты на батуте под руководством Святослава Колыхалова. Артисты Владимир Колыхалов, Александр Курганников, Степан Полторак, Аяна Дувананева, Денис Рожков являются лауреатами международного циркового фестиваля в Корее;
— Гимнаст на колесе смелости и воздушных полотнах Карен Сафарян продемонстрирует, что такое настоящее мастерство и ловкость;
— Акробаты на роликах восхитят завораживающими трюками. Своей ловкостью удивят Надежда Важдаева, Дмитрий Важдаев, Алексей Волков, Светлана Ярко;
— Ни один зритель не останется равнодушным, увидев гимнастов на банджи и ремнях. Под куполом цирка проявят своё мастерство Алла Кривченко, Валерия Тесцова, Марина Верейко, Артур Данилив;
— Уникальную дрессуру с бобтейлями и болонками покажет Надежда Важдаева;
— Эквилибристы на першах Екатерина и Рубен Сарадян очаруют каждого зрителя;
— Настоящим украшением программы является уникальный номер «Египетские зарисовки» Святослава Колыхалова;
— Публику ждет встреча с красочным номером «Восточные фрески». В свободной дрессуре верблюдов и джигитовке принимают участие Алла Кравченко, Валерия Тесцова, Екатерина Сарадян, Марина Верейко, Аяна Дуванаева, Верджиния и Заслуженный артист России Тигран Акопян;
— Клоун Эмиль Оганян докажет, что цирк — это искусство без слов. Не имея возможности слышать и говорить, артист блестяще используетязык тела и движений — пантомиму.

«Тропик шоу» — прекрасная возможность окунуться в атмосферу сказки, фантастического мира цирка и получить заряд положительной энергии.

Продолжительность: 2 часа 20 мин.

Дети младше 3 лет могут посетить представление бесплатно при следующих условиях:
— при наличии документа, подтверждающего возраст ребенка (свидетельство о рождении ребенка или запись в паспорте родителя),
— в сопровождении взрослого с билетом,
— с одним взрослым может прийти только один ребенок,
— без предоставления отдельного места.

На детей с 3 лет приобретается полный билет!',
