('Ladies’ Night',
'https://afisha.yandex.ru/samara/theatre_show/ladies-night-samarskii-teatr-dramy-im-gorkogo?source=rubric',
'Спектакль, ставший культовым! Это смешная и трогательная история о мужчинах, которые не перестают быть мужчинами даже в самые непростые времена.

В провинциальном городке закрылся металлургический завод, многие мужчины потеряли работу. И одному отчаявшемуся сталевару в голову приходит безумная идея - организовать стриптиз-шоу.

Только выступать в нём будет не профессионал из Нью-Йорка, а обычные мужики с металлургического завода, которые, правда, танцевать-то не умеют.

На протяжении всего спектакля смельчаки отчаянно пытаются научиться не совсем обычному и нелёгкому искусству, преодолевая внешние и внутренние препятствия.

В спектакле содержатся сцены демонстрации и курения табачных изделий.',
