('Оркестр CAGMO. Саундтреки Эйнауди. Концерт при свечах',
'https://afisha.yandex.ru/samara/concert/orkestr-cagmo-saundtreki-eynaudi-kontsert-pri-svechakh?source=rubric',
'CAGMO представляет концертную программу по мотивам творчества великого композитора — «Саундтреки Эйнауди при свечах» в исполнении струнных и фортепиано.

В программу добавлены треки из нового альбома The Summer Portraits: Sequence, Pathos.

Людовико Эйнауди — знаменитый итальянский композитор и пианист, один из самых выдающихся представителей современной классической музыки и автор саундтреков к таким популярным фильмам, как: «1+1», «Чёрный лебедь», «Это — Англия», «Земля кочевников» и многим другим. Проникновенная музыка композитора стала неотъемлемой частью сюжета знаменитого французского фильма «1+1» и навсегда влюбила зрителей в его творчество. Атмосферные саундтреки Эйнауди дополнили глубокий смысл кинокартины и сыграли важную роль в мировом признании французского фильма.

CAGMO представляет концертную программу с самыми яркими саундтреками знаменитого итальянского композитора — «Саундтреки Эйнауди при свечах». Уникальные симфонические аранжировки композиций в исполнении струнных и фортепиано подарят чувство погружения в атмосферу любимых кинокартин. Новое звучание знаменитых мелодий тронет до глубины души каждого, кто знаком с «1+1» и многими другими популярными фильмами.',
