('Беспринцыпные чтения',
'https://afisha.yandex.ru/samara/literary-reading/besprintsypnye-chteniia-2025-03-30?source=rubric',
'Александр Цыпкин в программе «Старый добрый Цыпкин».

Специальные гости — Максим Матвеев и Кристина Бабушкина

Литературно-театральный проект «БеспринцЫпные чтения» представляет специальную программу «Старый добрый Цыпкин». В исполнении Александра Цыпкина и его специальных гостей — известных актёров театра и кино Максима Матвеева и Кристины Бабушкиной —прозвучат лучшие рассказы автора. Истории, которые не только вас развеселят, но и дадут повод задуматься о жизни. Мы создадим праздничную атмосферу тепла и света, в которой захочется задержаться подольше.

«Старый добрый Цыпкин» — это программа для тех, кто считает, что, когда я был моложе, я был добрее. В общем программа составлена из классических хитов, конечно, не таких классических, как Питерский old school, но тем не менее все равно знакомых и всеми любимых«, — Александр Цыпкин.

О «БеспринцЫпных чтениях»
За девять лет проект достиг больших результатов.
— Прошло свыше тысячи выступлений по всей стране и миру.
— Фестиваль Короткой Новой прозы «БеспринцЫпные чтения» прошел в восьмой раз в Саду Эрмитаж и стал культовым городским мероприятием.
— Было открыто свыше 100 новых авторов современной прозы.
— Реализовано более 50 театральных постановок и экранизаций.
— Выпущено 7 сборников современных авторов и 10 книг самого Александра Цыпкина.

О «БеспринцЫпных чтениях»
Проект «БеспринцЫпные чтения» был создан в 2015 году Александром Цыпкиным и продюсером Анастасией Приц. Александр Цыпкин — современный российский писатель, драматург, сценарист, публицист, чьи книги становятся бестселлерами, а сериалы, снятые по сценариям Александра — «Беспринципные», «Что делать женщине, если...», «Министерство всего хорошего», — получают высокие рейтинги на разных стриминговых сервисах.

«БеспринцЫпные чтения» — один из самых ярких и необычных литературно-театральных проектов последнего времени. Его главной отличительной чертой и уникальной особенностью является то, что современную отечественную прозу со сцены читают не только ведущие российские актеры, но и сами авторы текстов. В России «Чтения» проходят на ведущих театральных и культурных площадках страны. Регулярно выпускаются сборники и собрания сочинений авторов проекта.

Открытый Фестиваль Короткой Новой прозы «БеспринцЫпные чтения» был организован восемь лет назад Александром Цыпкиным и продюсером Анастасией Приц. Проект нацелен на популяризацию современной литературы и её авторов. Традиционным местом проведения мероприятия является историческая площадка Сада Эрмитаж. Участие авторов и чтецов происходит на конкурсной основе. Отобранные произведения звучат в исполнении самих авторов и ведущих российских актеров.

География проекта: Барнаул, Белгород, Владивосток, Волгоград, Воронеж, Екатеринбург, Иваново, Ижевск, Иркутск, Казань, Калининград, Кострома, Краснодар, Красноярск, Курск, Москва, Мурманск, Нижний Новгород, Новосибирск, Норильск, Омск, Пермь, Петрозаводск, Ростов-на-Дону, Самара, Санкт-Петербург, Сочи, Тверь, Томск, Уфа, Хабаровск, Челябинск, Южно-Сахалинск, Ярославль.

А также проект побывал на гастролях в Великобритании, Германии, Казахстане, на Кипре, в ОАЭ, Сингапуре, США, во Франции, в Швейцарии и ряде других стран.

В разное время участниками проекта «БеспринцЫпные чтения» были известные артисты.

Актёры: Аброськина Маргарита, Бабушкина Кристина, Борисов Юрий, Бурковский Андрей, Бурунов Сергей, Виторган Максим, Верник Игорь, Гармаш Сергей, Глюк’oZа, Горевой Михаил, Дапкунайте Ингеборга, Дергилева Валерия, Деревянко Павел, Дроздов Николай, Ильяшенко Лукерья, Исакова Виктория, Каневский Леонид, Козловский Данила, Косточкин Антон, Котюх Сергей, Крон Маргарита, Куценко Гоша, Лидов Петр, Ляпина Валентина, Максимова Полина, Маликова Полина, Матвеев Максим, Мерзликин Андрей, Миронова Анна, Михалкова Анна, Михалкова Надежда, Сабуров Нурлан, Собчак Ксения, Стычкин Евгений, Сутулова Ольга, Табаков Павел, Тарасова Аглая, Толстоганова Виктория, Тройник Михаил, Фоменко Николай, Хабенский Константин, Чеботарев Дмитрий, Шпица Катерина.',
