('Максим Аверин. Научи меня жить',
'https://afisha.yandex.ru/samara/monoperformance/maksim-averin-nauchi-menia-zhit?source=rubric',
'«Научи меня жить» — новая версия легендарного моноспектакля Максима Аверина «Всё начинается с любви». Его за последние годы посмотрели более 500 тысяч зрителей в 248 городах России в 18-ти странах мира. В новом спектакле собраны как лучшие произведения предыдущего спектакля, так и новые композиции.

Народный артист России Максим Аверин — один из ведущих и популярных отечественных актёров, успешный киноактёр, ведущий телешоу на Первом канале, режиссёр. Его фильмография насчитывает более 50 фильмов и сериалов.

Моноспектакль «Научи меня жить» обещает расширить представление зрителей о возможностях и таланте этого замечательного артиста. Это не творческая встреча, не концерт, — это именно спектакль со своей драматургией, полноценное театральное действо, продуманная и искусно сложенная мозаика из музыки, поэзии и прозы, сопровождающаяся мастерской звуковой и световой партитурой. Актёр остаётся один на один с публикой и открывает свою душу в этом диалоге.

В программе: стихи и проза Давида Самойлова, Александра Вертинского, Роберта Рождественского, Евгения Евтушенко и других прекрасных авторов, песни советских и российских композиторов.

Максим Аверин из тех артистов, кто ведёт за собой зрителя, находя в нём искреннего слушателя и собеседника. А положительная энергия, излучаемая актёром, дарит вдохновение и мечту, проникая в самое сердце.',
