'Театральный фестиваль «Школьная классика» рекомендует спектакль к просмотру школьникам.

Спектакль театра «Камерная сцена» по знаменитой повести А. С. Пушкина — о России, о невозможности понять ее историю, о непостижимой тайне русского характера, в котором уживаются столько противоположностей: романтизм, мечтательность, стремление в горные выси, широта души — и лень, тяга к хаосу и беспорядку, иррациональная тоска. И, конечно, это спектакль о любви — чистой, юношеской, самоотверженной, бескомпромиссной.

