('Александр Невский',
'https://afisha.yandex.ru/samara/concert/aleksandr-nevskiy-2025-05?source=rubric',
'В основе музыкального текста кантаты «Александр Невский» — музыка Сергея Сергеевича Прокофьева к одноимённому фильму Сергея Михайловича Эйзенштейна «Александр Невский», снятому в 1938 году. Вокальные партии написаны на стихи советского поэта, журналиста, военного корреспондента Владимира Александровича Луговского в 1939 году. Впервые кантата была исполнена в Большом зале Московской консерватории 17 мая 1939 года под управлением автора.

Исполнение кантаты будет сопровождаться литературными фрагментами из поэмы «Ледовое побоище» советского поэта, драматурга, военного корреспондента Константина Михайловича Симонова. Поэма была написана в 1937 году, в год начала работы Эйзенштейна над фильмом «Александр Невский».

Во время исполнения на экране будут показаны картины русских художников с изображением Александра Невского и подходящих к сюжету картин. Зрителей ждет необыкновенный вечер: удивительная музыка, потрясающий текст и прекрасные произведения живописи создадут уникальный синтез.

