Симфонический оркестр и хор Самарского академического театра оперы и балета имени Д. Д. Шостаковича
Солистка — Анастасия Вечёркина (меццо-сопрано)
В проекте принимает участие артист Самарского академического театра драмы имени М. Горького Денис Евневич',
