'Алексей Архиповский — «Паганини русской балалайки».

Архиповский желанный гость на самых престижных концертных площадках мира. Ему аплодировали президенты и королевские особы, его выступления принимаются зрителями с восторгом, где бы он не играл — на лужайке Белого Дома или в церковном соборе, на стадионе или камерном концертном зале. Виртуоз попал в российскую книгу рекордов в номинации «Лучший в мире балалаечник».

Сам Алексей считает свой треугольный инструмент кладезем тайн и загадок, подобным загадочной пирамиде Хеопса. Он не устает их разгадывать, а значит — удивлять свою благодарную публику новыми находками и открытиями.',
