('Надежды маленький оркестрик… Булат Окуджава',
'https://afisha.yandex.ru/samara/concert/nadezhdy-malenkii-orkestrik-bulat-okudzhava?source=rubric',
'Программа составлена из стихов и прозы знаменитого поэта-фронтовика, ставшего своеобразной поэтической «совестью» целой эпохи — середины ХХ века. Его «песенки», как их называл сам поэт: «Бумажный солдат», «Песенка об Арбате», «До свидания, мальчики», «Не клонись, моя головушка», «Маэстро» и другие, — запоминались с первого прослушивания, уходили «в народ» и пелись огромным количеством людей. Незатейливые, на первый взгляд, тексты Окуджавы говорили о добре, совести, справедливости с такой искренностью и так убедительно, что стали нравственной опорой для целого поколения.

Тема Великой Отечественной войны пронизывает всё творчество Булата Окуджавы. Специально для этой программы созданы оркестровые аранжировки знаменитых песен Окуджавы, что, несомненно, увеличило силу эмоционального воздействия на слушателей

