'Эта музыкальная феерия возвращает зрителей к юности, мечтам и первой любви, заставляя верить в то, что чудеса все-таки случаются. Историю про «Алые паруса» знают, пожалуй, все. И во время спектакля, погружаясь в атмосферу сказки, даже самые серьезные сердца могут растаять, услышав великолепное пение актеров.

