('Авангард Леонтьев. Пушкин: поэмы «Медный всадник» и «Граф Нулин»',
'https://afisha.yandex.ru/samara/cinema_show/avangard-leontev-pushkin-poemy-mednyi-vsadnik-i-graf-nulin?source=rubric',
'Народный артист России Авангард Леонтьев исполняет и комментирует поэмы Александра Пушкина «Медный всадник» и «Граф Нулин». Комментарии сопровождаются видеопоказом рукописей, портретов и фотографий.

Мало кто из современных артистов так тонко чувствует литературное слово и так глубоко знает русскую литературу, как народный артист России Авангард Леонтьев. Сам он определяет жанр своих спектаклей как «звучащее слово». Вечер с Авангардом Леонтьевым по форме может быть и похож на традиционный «чтецкий концерт», но по сути они — нечто гораздо большее: это еще и разговор с внимательным и чутким собеседником, предлагающим увлекательное путешествие в русскую литературу, лучше других знающим, как сделать слово объемным, живым, сильным и волнующим, как разглядеть на знакомых (или незнакомых — Леонтьев выбирает не самые известные произведения) страницах неожиданные смыслы.

Звучащая словесность Авангарда Леонтьева — почти осязаемая реальность, столь увлекательная, что зритель забывает обо всем, что осталось за дверями зрительного зала.

Исполнители:
Народный артист РФ, лауреат Государственной премии РФ, артист МХТ им. Чехова Авангард Леонтьев',
