('Ирина Богушевская',
'https://afisha.yandex.ru/samara/concert/irina-bogushevskaya-2025?source=rubric',
'Ирина Богушевская — певица, актриса, автор всего своего репертуара. Считает себя наследницей песенного жанра, созданного Вертинским, в котором мелодия, смысл и актерское мастерство одинаково важны. Поэтому музыка и театр в творчестве Богушевской слиты воедино. Каждая из её автобиографичных песен-историй — это мини-спектакль, целая маленькая жизнь, прожитая за 3–4 минуты.

Ирина является обладателем Гран-при конкурса Актерской песни им. А. Миронова. Презентации её сольных альбомов проходили во МХАТе им. Горького, Зале Чайковского, Крокус Сити Холле, в Театральном зале ММДМ. Сборник песен и стихов Ирины вышел в издательстве ЭКСМО в «Золотой серии поэзии».

В отзывах ей пишут: «этот концерт — лучшее средство от депрессии», «это был сеанс музыкальной терапии», «огромный заряд горячего, доброго, светлого удовольствия», «захотелось жить и верить в лучшее».

Приходите! Будем петь и верить в лучшее вместе.',
