Выступал под управлением дирижеров Юрия Симонова, Василия Синайского, Гинтараса Ринкявичуса, Павела Герштейна, Кирила Карабица, Фредерика Шаслена, а так же в ансамблях с такими музыкантами, как Ицхак Перльман, Дональд Вайлерстайн, Памела Франк, Антуан Тамести, Андрей Баранов, Нобуко Имаи, Василий Лобанов и многими др.

Анастасия Белугина (скрипка) родилась в 2009 г. в семье музыкантов. Занимается на скрипке в «Мастерской Скрипичного Искусства» в классе доцента Белугиной Марии Андреевны. Выступала в качестве солиста с камерными и симфоническими оркестрами под руководством Михаила Бенюмова, Павла Герштейна, Игоря Лермана, Владимира Кима, Федора Белугина, Александра Хургина, Андрея Рейна, Дмитрия Крюкова, Виктора Сороки. Выступала на многих известных российских сценах в ансамбле с такими музыкантами, как Андрей Баранов, Даниил Австрих, Матвей Блюмин, квартет имени Давида Ойстраха. Участница всероссийского телевизионного проекта «Вундеркинды» в двух номинациях «Скрипка» и «Балет». С 2019 года является солисткой «Мастерской Скрипичного Искусства». Стипендиат фонда «Новые имена» под руководством Дениса Мацуева.

Андрей Похлебаев (скрипка) — Победитель XV Международного конкурса классической музыки VIVA-MUSIC, лауреат 1 премии IV открытого Всероссийского конкурса скрипачей им. Турчаниновой и I Международного конкурса инструментального исполнительства им. Евы, Иосифа и Семена Коган. Массу наград Андрей получил в 2022 г., например, он оказался лауреатом V Международного конкурса скрипачей им. Янкелевича и стипендиатом «Новых имен». В 2023 победил в конкурсе солистов «Свет надежды», а также получил именную стипендию Международного благотворительного фонда Владимира Спивакова. С 2022 года солист «Мастерской Скрипичного Искусства».

Никита Сенько (скрипка). Родился в г. Железногорск (Красноярский край), где получил свое первое музыкальное образование. С 2019 года ученик «Мастерской скрипичного Искусства» — класс доцента Белугиной Марии Андреевны. Никита является лауреатом Всероссийских и Международных конкурсов. С 2020 года — солист «Мастерской Скрипичного Искусства». Выступал в качестве солиста с камерными и симфоническими оркестрами под руководством Павла Герштейна, Федора Белугина, Александра Хургина, Андрея Рейна, Дмитрия Крюкова. Играл на многих известных российских сценах, выступая в ансамбле с Андреем Барановым, Даниилом Австрихом, Федором Белугиным, Матвеем Блюминым.

