'https://afisha.yandex.ru/samara/concert/vashi-pelmeni-viacheslav-miasnikov-i-andrei-rozhkov-show?source=rubric',
'Друзья!

Мы, Вячеслав Мясников и Андрей Рожков, приготовили для вас потрясающую, новую шоу-программу!

Вести ее будет неповторимый Артём Пушкин!

Наш творческий потенциал и стремление приводить в восторг любимого зрителя — вот то, что вдохновило и помогло создать для вас наше новое Шоу, с которым мы, обязательно, будем и в вашем городе! В шоу включены как самые любимые вами номера, так и абсолютно новые!

Так что, друзья, не пропустите, ждем вас на наших концертах и обещаем вам, как всегда, прекрасную, неповторимую атмосферу, динамичную программу и потрясающее настроение!

