('Олена Уутай',
'https://afisha.yandex.ru/samara/concert/olena-uutai?source=rubric',
'Шоу такого формата не часто встретишь. Именно в этот день каждый зритель сможет восполнить свою духовную энергию сполна! Встреча с представителем уникальной музыки Оленой Уутай! Это человек, поющий на языке самой природы.

Певица использует несколько видов северного горлового пения, при этом не обычных, а имитирующих звуки природы и её явления, голоса разнообразных птиц и животных. Играет на варганах разных этносов, шаманских бубнах, флейтах и совмещает всё это в формате ультрасовременного звучания — от аутентичного древнего корневого звука к новым краскам и ритмам будущего.

Этно-музыкант, вокалистка, виртуоз игры на варгане, и мастер горлового пения — Олена Уутай обещает уникальный и неповторимый концерт, который перенесет вас в мир древних традиций и загадочной красоты музыки северных народов России.

Кроме того, она мастерски владеет инструментом «хомус». Его звучание способно помочь людям не только вспомнить о своих корнях, но также открыть нечто новое, перенеся их в другое музыкальное пространство. По поверью народов Севера, древние вибрации хомуса очищают, наполняют силой и энергией, даруют гармонию и восстанавливают в человеке баланс трёх начал.

Олена УУТАй— признанный во всем мире этно-музыкант, мастер горлового пения, певица, композитор, автор нео-шаманских практик из Якутии. Олена удостоена звания «Легенда этномузыки» по версии крупного фестиваля мировой музыки SayanRing, отмечена наградой правительственного уровня «Отличник Культуры Республики Саха (Якутия)» за вклад в развитие национальной культуры. Полуфиналист Britain’s Got Talent (Великобритания), Финалист Das Supertalent (Германия).

Непревзойденная харизма и талант Олены Уутай давно уже прочно завоевали сердца поклонников по всему миру. Её исполнения наполнены духом природы, магии звуков и душевного трепета. Каждая нота, каждый звук — это гармония с прошлым и призыв к будущему, объединяющая века и культуры. Сегодня во всём мире Уутай стала лицом варгана, по её видео-урокам учатся играть как начинающие так и профессиональные музыканты.

Концерт Олены Уутай станет истинным праздником музыки, культуры и души. Погружайтесь в атмосферу неисчерпаемой творческой энергии и слитности с природой вместе с одной из величайших представительниц этно-музыки.

Не упустите возможность стать частью этого уникального события!',
