'https://afisha.yandex.ru/samara/theatre_show/don-zhuan-akademicheskii-teatr-dramy-im-gorkogo?source=rubric',
'Главный герой в спектакле не совсем похож на традиционный, запечатленный в человеческом воображении образ. Александр Морфов существенно раздвинул рамки первоисточника.

 В спектакле нет никакой показной романтики, его герой порою откровенно брутален! Для него по существу нет ничего святого! Беззаботно порхая по жизни, легко и изящно избегая опасных конфликтов, он, тем не менее, остается циничным и вероломным. «Никто не скажет, что я способен раскаяться», – утверждает Дон Жуан. Его жизненный девиз предельно прост: дважды два – четыре. Такова в спектакле истинная суть натуры Дон Жуана!',
