('Juan Horlendis Band',
'https://afisha.yandex.ru/samara/concert/juan-horlendis-band-2025?source=rubric',
'Купите билеты на концерт Juan Horlеndis Band! Погрузитесь в атмосферу латиноамериканской и кубинской музыки, где каждый аккорд и ритм наполнят ваше сердце радостью и энергией.

В программе — румба, сальса, бачата, тимба и множество других стилей, которые перенесут вас в мир вечного лета и ярких эмоций.

Вы услышите известные композиции Карлоса Сантаны, Сезарии Эворы, Анжелики Киджо и других легенд, в исполнении настоящих кубинских музыкантов.

Хуан Орлендис — фронтмен, жизнерадостный мультиинструменталист, вокалист, педагог. Он — вихрь энергии, музыкант, чья страсть к искусству зажигает сердца. В руках Хуана оживают бас-гитара, гитара, рояль и зажигательные латиноамериканские перкуссии. Его творчество пронизано кубинским духом: от зажигательных ритмов до мелодий, которые заставляют сердца биться быстрее.

Не упустите шанс стать частью этого музыкального праздника! Приходите за солнечным настроением, любовью и улыбками.

Хуан Орлендис, вокал, гитара

Данил Прокопьев, известный петербургский музыкант, барабанщик и перкуссионист, один из самых ярких представителей латинской музыки в Петербурге, прекрасно владеет афро-кубинскими, колумбийскими, бразильскими и многими другими стилями на барабанной установке и перкуссии.

Максим Соболев, талантливый пианист, композитор, аранжировщик.

Рауль Александр Марти Авила, кубинский трубач, после музыкальной школы и колледжа с отличием окончил Высший институт искусств в Гаване. С 2010 года живет и выступает в России

Хуан Карлос «Каскара», перкуссия, вокал (Куба).',
