Александр Шоуа — известный артист и композитор, чьи песни проникают в самое сердце и остаются там надолго. Его уникальный стиль: сочетание романтики и глубоких смыслов, а также харизма на сцене — делают каждое его выступление незабываемым. В этот вечер зрители смогут услышать как уже полюбившиеся хиты, так и новые композиции, которые обязательно покорят сердца зрителей.

