('Корсиканка',
'https://afisha.yandex.ru/samara/theatre_show/korsikanka-samarskii-teatr-dramy-im-gorkogo?source=rubric',
'Иржи Губач – чешский драматург и сценарист, до 1955 года работал инженером. После перенесенного заболевания начал писать. Самое известное его произведение для театра – «Адьютантша его императорского величества» («Корсиканка»). В своих пьесах Губач часто поднимает политические и нравственные вопросы бытия.

Действие «Корсиканки» происходит в 1819 году на острове Святой Елены. Добровольно сдавшись англичанам, французский император Наполеон Бонапарт оказывается пленником. Он вынужден жить в унизительных условиях под охраной, в изгнании и одиночестве влачить свое существование, забыв о том, что некогда он был великим Наполеоном. Неожиданно на острове появляется Жозефина Понтиу – кухарка и простолюдинка, преодолевшая более двух тысяч миль по штормящему морю, чтобы привезти поклон от парижского люда. Император польщен, но еще не догадывается, для чего на самом деле прибыла на остров незваная гостья.',
