'https://afisha.yandex.ru/samara/cinema/vsio-chto-tebia-kasaetsia?source=rubric',
'Маша — шестнадцатилетняя школьница, которая никогда не видела своего отца. Мать говорит ей, что папа их бросил, когда девочка еще не родилась, и не хотел участвовать в их жизни. Однажды, разбирая старые фотографии для выпускного вечера, Маша находит письмо, которая мама писала отцу и узнает что его зовут Павел Соколов, и что её родители познакомились на концерте группы «Звери» 18 лет назад, а потом он ушел в армию и писем от него не было. Маша находит подходящего по имени, фамилии и возрасту мужчину в VK — правда, без фото. На странице Павла она видит пост о том, что он идет на юбилейный концерт группы «Звери». Маша убеждена, что это её отец и решает тоже отправиться на концерт, найти его и узнать, почему он их оставил.',
