('Владимир Нестеренко и Дмитрий Сабуров',
'https://afisha.yandex.ru/samara/concert/vladimir-nesterenko-i-dmitrii-saburov?source=rubric',
'Владимир Нестеренко — джазовый полиинструменталист, единственный профессиональный российский органист, исполняющий джаз. Лауреат многочисленных премий, среди которых «Надежда российского джаза» от Джаз.Ухо (Ассоциация российских джазовых журналистов), Гран-при Первого международного джазового конкурса «ДоДж 2001» (Украина, Донецк), Всероссийского конкурса джазовых исполнителей 2003 года (Россия, Ростов-на-Дону). Со своим сольным проектом в 2001 году он принимал участие в Международном джазовом фестивале, посвящённом памяти У. Коновера в Москве. В 2001 и 2004 годах его принимали площадки «Усадьбы Джаз», Jazz voices (Германия), 2005 (в квартете польского саксофониста З. Намысловского) и 2007 (с Петром Войштаком) годах.

Владимир Нестеренко неоднократно сотрудничал с польскими музыкантами в качестве органиста и флейтиста. В копилке исполнителя гастрольная деятельность и студийные записи с Дидье Локвудом, Стивом Слаглом, Майлзом Гриффитом, Джо Фордом, Грегом Банди, Грегори Портером, Игорем Бутманом, Даниилом Крамером и многими другими джазовыми светилами отечественной и зарубежной сцены.

Дмитрий Сабуров (ударные/Москва) — один из самых востребованных и ярких барабанщиков Москвы. Дмитрий учился у выдающихся барабанщиков эпохи — Joe Farnsworth (Нью Йорк) и Jason Brown (Нью Йорк). В настоящее время он играет с самыми лучшими музыкантами нашей страны и зарубежными артистами, среди которых: Яков Окунь, Михаил Окунь (зас. Артист России), Владимир Нестеренко, Олег Стариков, Todd Herbet, Emmet Cohen, Benito Gonzales, Armir Lee и многие другие.

Дмитрий — приверженец настоящего джаза и свинга. Помимо этого создал самую большую и сильную команду по организации туров по всей России с участием звёзд российского джаза. Директор Международного Джазового Фестиваля «JazzMore», который пройдёт в этом году в июне в г. Сочи Зимний театр.',
