('Артур Руденко',
'https://afisha.yandex.ru/samara/concert/artur-rudenko-2025-04?source=rubric',
'Артур Руденко — уже состоявшаяся в звезда в жанре лиричной, пронзительной, наполненной любви к женщине песни. Подтверждение этому — сотни тысяч подписчиков в социальных сетях и десятки миллионов просмотров его клипов. Артур — неоднократный лауреат премии «Шансон года», постоянный участник проектов «Эх, разгуляй!», «Славянский Базар», а хиты «Падал белый снег», «Забыть нельзя», «Счастье ты мое голубоглазое», «Один на двоих отель» — это визитная карточка артиста. Каждый концерт Артура Руденко — это лучшие и новые песни, а так же незримая теплая связь с каждым зрителем в зале.',
