97),
('Александр Бессонов. Одиссея мужчины среднего возраста',
'https://afisha.yandex.ru/samara/literary-reading/odisseia-muzhchiny-srednego-vozrasta?source=rubric',
'«Одиссея мужчины среднего возраста или путевые заметки» — новая программа Александра Бессонова. В ней рассказывается о приключениях мифических героев, которые ездят с литературными вечерами из города в город. По дороге они встречают проводницу Горгону, одноглазого охранника в караоке клубе и сладкоголосых Сирен из Калининграда... А дома их ждут жёны, к которым выстроилась очередь из женихов...

Александр Бессонов — мастер короткой прозы из Новосибирска. Автор книг «Чарли», «Добрее» и «Мадам», победитель фестиваля «БеспринцЫпные чтения» с рассказом «Граф Монте-Кристо». Трогательные и полные светлого юмора истории Александра Бессонова полюбились его многочисленным подписчикам в соцсетях. Его рассказы с большим удовольствием читают со сцены Катерина Шпица, Павел Деревянко, Максим Матвеев и другие резиденты «БеспринцЫпных чтений». «Мадам» одна из самых продаваемых книг в 2023. Тираж более 20 000.',
'от 800 ₽',
