5217428966352364775,
'2025-04-30 19:00:00',
98),
('Международный день джаза',
'https://afisha.yandex.ru/samara/concert/mezhdunarodnyi-den-dzhaza-2025-04-30?source=rubric',
'Что же такое джаз?

Джаз разрушает барьеры и создаёт возможности для укрепления взаимопонимания и терпимости;
Джаз — это вектор свободы выражения мнений;
Джаз снижает напряжённость в отношениях между отдельными людьми, группами и сообществами;
Джаз поощряет художественную креативность, импровизацию, новые формы самовыражения и слияния традиционных и новых музыкальных форм;
Джаз стимулирует межкультурный диалог и расширяет возможности молодых людей из маргинализированных общин.

Как сказала великая Нина Симоне, «Джаз — это не просто музыка, это образ жизни, метод бытия и стиль мышления».

Джазовое движение отпразднует этот день фестивалем с самыми яркими джазовыми коллективами города, которые создают джазовую жизнь нашего города!',
