('Ярослав Сапожинский и Jеo Band',
'https://afisha.yandex.ru/samara/concert/yaroslav-sapozhinskiy-i-jeo-band?source=rubric',
'Ярослав Сапожинский — композитор, пианист, саунд-продюсер, премиум-артист мирового музыкального дистрибьютора OneRPM в кластере джазовой музыки. Его произведения в ротации радио «Джаз» и редакционных плейлистах мировых музыкальных площадок. Ярослав стал героем передачи «Клуб Шаболовка 37» на телеканале «Россия Культура», эфиры с ним можно услышать на радио «Джаз», «Маяк» и других.

