('Джаз из солнечной Армении: вдохновение от Соны и Рафаэля',
'https://afisha.yandex.ru/samara/concert/dzhaz-iz-solnechnoi-armenii-vdokhnovenie-ot-sony-i-rafaelia-2025-05-16?source=rubric',
'Чарующая, прекрасная, обладательница мягчайшего медового тембра, джазовая вокалистка, музыкант, композитор Сона Гюлхасян вместе с виртуозным пианистом, аранжировщиком и композитором Рафаэлем Петросяном исполнят свою великолепную джазовую программу в предстоящем российском туре!

Сона и Рафаэль начали выступать совместно в 2022 году. Они основали лейбл с провокативным названием SheetHappens и свой джаз-оркестр, который в настоящее время ведет активную творческую деятельность.

Совсем недавно дуэт успешно выступил на фестивале Ararat джаз-пикник «Счастливые gоют» в городе Алматы, где покорил публику Казахстана. Музыканты также выступили в джаз клубе EverJazz в Алмате.

Сона Гюлхасян родилась в 1999 году в городе Ереван. С 4 летнего возраста обучалась вокалу в вокальной студии «До-Ре-Ми». В 2014 году поступила в общеобразовательную муз. школу имени П. И. Чайковского, училась на музыковеда-теоретика. Является лауреатом и победительницей многих международных конкурсов по вокалу. 2011 году в Берлине участвовала на конкурсе «Berliner Perle», где стала обладательницей Гран-при. 2012 году заняла 2 место, на детской «Новой Волне», в городе Ялта. С 15 летнего возраста Сона являлась вокалисткой разных популярных рок и поп групп Армении. С 2018–2022 гг. взяла перерыв в музыке в связи с учёбой и получила два высших образования в качестве лингвиста и юриста. В 2022 году познакомившись с пианистом Рафаэльем Петросяном снова начала активно заниматься музыкальной деятельностью.

Рафаэль Петросян — молодой пианист из Армении, произведший фурор на джазовой сцене! 30 летний музыкант родился и вырос в Ереване и обучался... медицине, однако в 22 года, открыв для себя джазовую музыку, оставил учебу незавершенной. Рафаэль потратил годы на самообразование и обучаясь у мэтров армянской джазовой сцены. Пианисты Ваагн Айрапетян и Карен Григорян, барабанщик Армен Тутунджян стали наставниками молодого музыканта и высоко отзывались о таланте Рафаэля Петросяна. Рафаэль выступает со своим трио и квартетом, и является пианистом в группах Arm. Strong Dixie и Arm. Strong Orchestra. В 2021 году он участвовал в международном конкурсе «Мир lжаза», выступал с зарубежными музыкантами такими как трубач и вокалист Ларри Гиллеспи, трубач Джон Маршалл, контрабасист Николай Затолочный, вместе с Левоном Малхасяном является соавтором Антологии Армянского Джаза.',
'от 700 ₽',
