('Yubu',
'https://afisha.yandex.ru/samara/concert/yubu-2025-05-31?source=rubric',
'Трибьют-шоу — шоу, в котором песни известных групп или артистов звучат в исполнении других музыкантов. Группы или артисты, чьи произведения исполняются, на мероприятии не присутствуют.

Yubu — автор и исполнитель, который смело смешивает музыкальные традиции разных культур, создавая уникальный стиль, пропитанный глубиной и эмоциональностью.

Его музыка — это смелый микс регги, блюз-рока, фанка, соула и афробита, который превращает каждое выступление в яркое и захватывающее шоу, способное тронуть сердца слушателей по всему миру.

В его программе не только авторские композиции, но и захватывающие интерпретации классики, включая легендарные песни Боба Марли, которые он исполняет с особой душой и энергией.

Каждая песня — это страсть, энергия и искренность. От первых аккордов гитары до проникновенных текстов, от ностальгически-запоминающихся мелодий до мощного звучания — Yubu погружает слушателей в атмосферу живой музыки, которую невозможно забыть.

Почувствуйте ритм. Прочувствуйте эмоции. Откройте для себя Yubu.',
