('Сердце моё в сердце твоём живет',
'https://afisha.yandex.ru/samara/concert/serdtse-moio-v-serdtse-tvoiom-zhivet?source=rubric',
'После этого вечера вы не будете прежними, потому что побываете в другом измерении, в которое унесут вас песни Елены Фроловой на стихи Цветаевой, Губанова, Бродского, Маховой, Родионовой и свои собственные.

Уникальный голос, незабываемая интонация, неординарное композиторское мышление, виртуозное владение шестиструнной гитарой, обаяние и энергетика — всё это прекрасная Елена Фролова. Вдохновляющая, окрыляющая, просветляющая, «женщина, которая ходит по воздуху» — это тоже она.

В концерте принимает участие пианист Иван Ялынский (г. Москва)-oбладатель Гран-При фестиваля «Петербургский аккорд», дипломант Грушинского фестиваля, лауреат Международных конкурсов по классу рояля.

Елена Фролова — русская певица, поэт, композитор, актриса Театра музыки и поэзии под руководством Камбуровой. Лауреат Премии им. Веры Матвеевой (1993). Постоянный член жюри различных фестивалей авторской песни, в том числе Международного фестиваля им. Грушина и Международного фестиваля «Петербургский аккорд». лауреат Волошинской премии 2021 года в номинации «За вклад в культуру».

С 1991 года Елена активно гастролирует с сольными программами. География её концертов огромна: многие города России, Белоруссия, Украина, Латвия, Эстония, Литва, Германия, Италия, Франция, Израиль, Бельгия, Швейцария, Швеция, Мексика, Испания, Греция.

Елена Фролова выступала на таких площадках как Théâtre de la Ville, Théâtre des Abbesses в Париже, Teatro de las Tres Culturas, Teatro de la República в Мексике, ей аплодировали залы Барселоны, Мадрида, Брюсселя и Антверпена. С 2008 года — она постоянная гостья Фестиваля искусств на острове Наксос (Греция). Елена Фролова написала и исполнила музыкальное сопровождение к мультипликационному фильму «Легенда о леди Годиве» (реж. Ирина Кодюкова, 2004 г.). В мультипликационном фильме «Моя любовь» (реж. Александр Петров, 2006 г.) она исполнила романс «На заре ты её не буди». В фильме «Географ глобус пропил» (реж. Велединский, 2013г. — главный приз российского фестиваля «Кинотавр») за кадром звучит русская народная песня «Летел голубь» в исполнении Елены Фроловой.

В 2007 году в издательстве «Вита Нова» вышла книга стихов Елены Фроловой «Песня для Эвридики». В декабре 2013 года на Российском фестивале авторского документального кино «АРТДОКФЕСТ-2013» в программе «СРЕДА» в Москве состоялась премьера фильма Ирины Рёриг и Акселя Брандта (Германия) «Три героини в поисках Родины», посвященного творчеству Елены Фроловой.

С 2014 г. Елена Фролова — организатор и вдохновитель музыкального фестиваля «Гусли мира», проводимого в г. Суздале.

В 2024 г. вышла книга стихов и песен Елены Фроловой «Стихи и песни». За годы творческой деятельности Еленой Фроловой сочинено более 800 музыкальных композиций. В репертуаре свыше 1000 песен. Дискография насчитывает порядка 50 альбомов.

Елена Камбурова: «Но не проживаете ли вы истинно настоящую жизнь именно в те минуты, когда невидимая нить связывает вас с миром этих песен, с голосом Елены Фроловой, внутри которого вы сумеете расслышать звон маленького колокольчика. Он-то может и есть самый главный проводник в те миры и пространства, которых не видать нам из-за смога, нависшего над нами, имя которому — суета!»',
