'Произведения Агаты Кристи стали одними из самых публикуемых за всю историю человечества, уступая только «Библии» и Шекспиру. Режиссер Миша Лебедев: «Агата Кристи – классик жанра. «Десять негритят» – великий, один из лучших детективных сюжетов. Что может произойти с десятью абсолютно незнакомыми людьми, оказавшимися запертыми на острове? Тайны, подозрения, животный страх и встреча со смертью, всё это предстоит пройти героям этой истории. А в итоге… Добро пожаловать в таинственный и манящий мир Агаты Кристи».',
