'Живут в городке Черемухине обнищавшие дворяне с говорящей фамилией – Прежневы, кичатся своим дворянством перед соседями – купцами, а сами мечтают о невесте с большим приданым. Легкомысленному трутню Полю Прежневу удается обманом жениться на богатой купеческой дочке, простодушной Серафиме, поверившей в его любовь. Но, разумеется, правда выплывет наружу и обманутыми окажутся дворяне. Восторжествуют природный ум, юмор и смекалка народа. Знай наших! В спектакле много музыки, танцев и театральных шуток.',
