'Корабль доброго инопланетянина Ждуна потерпел крушение во время метеоритного дождя и упал в лесу недалеко от Абрау-Дюрсо. Ждун посылает сигнал бедствия в космос и начинает ждать помощи, но есть незадача — до его планеты 5 световых лет, и ждать пришлось бы долго. К счастью, на помощь Ждуну приходит любознательный мальчик Никита, а позже подтягивается и вся его семья. Никите и семье Семёновых предстоит помочь пришельцу отремонтировать корабль, избежать козней местного афериста-бизнесмена, который страстно мечтает завладеть инопланетными технологиями, и вернуться домой. А Ждун заново научит семью Семёновых слышать и понимать друг друга, и покажет, что в чрезвычайной ситуации даже обычный человек может стать супергероем.',
