136),
('Метод Гронхольма',
'https://afisha.yandex.ru/samara/theatre_show/metod-gronkholma-mesto-deistviia?source=rubric',
'«Хорошие люди остаются за бортом»

В офисе одной крупной мадридской компании собираются четыре кандидата на должность финансового директора компании, которым предстоит пройти собеседование. Компания хочет отобрать из них единственного кандидата, достойного занять эту крупную должность.

Когда герои оказываются в одном помещении, выясняется, что никто из фирмы не собирается с ними беседовать; вместо этого кандидатам выдаются задания, с которыми им надо сообща справиться. Деловая встреча перерастает в бесчеловечную игру: чтобы занять престижную должность, кандидатам необходимо выполнить абсурдные и жестокие задания, безжалостно расправившись с конкурентами.

Суть этого «Метода Гронхольма» в том, чтобы заставить самих соискателей решить, кто из них лишний. Однако никто из них не собирается уступать.',
