('Марсу нужны любовники',
'https://afisha.yandex.ru/samara/concert/marsu-nuzhny-lyubovniki-tour?source=rubric',
'Уральский индипоп квартет, появившийся в начале 2010-х. За плечами коллектива: пять альбомов, десятки синглов, ремиксов, фестивалей и концертов от Чукотки до Петербурга.

Песни «Её глаза» и «Ветер сдувает с крыш» неоднократно попадали в топ музыкальных сервисов и продолжают находиться в эфирах радио и ТВ. Песни ребят звучат в саундтреках к российским полнометражным фильмам и сериалам, а в картине «Отпуск» телеканала ТНТ группа снялась полным составом в роли самих же себя.

За время своего существования четверка обрела статус романтиков, космонавтов и мечтателей, а также стала известна по совместным работам с «Мумий Тролль», «Сансара», Варварой Визбор, Феликсом Бондаревым, Инной Стил и многими другими знаковыми артистами.',
