'В пьесе Питера Шеффера «Амадеус» одно из главных действующих лиц — музыка. Сальери — первый придворный капельмейстер Вены, прославленный педагог, проживает лучшие годы своей музыкальной карьеры при императоре Иосифе II. Но, внезапно, у него появляется конкурент — взбалмошный, непристойный Моцарт, который с ребяческой легкостью творит шедевральные произведения музыкального искусства, озаренный божественным даром. И зависть начинает разъедать душу Сальери...',
