('Мульт в кино. Выпуск № 181. Нам 10 лет!',
'https://afisha.yandex.ru/samara/cinema/mult-v-kino-vypusk-181-nam-10-let?source=rubric',
'Интерактивный киножурнал «МУЛЬТ в кино» отмечает 10-летний юбилей! В праздничном выпуске — новые эпизоды мультсериалов «Ми-ми-мишки», «Кошечки-Собачки», «Волшебная кухня», эксклюзивный фрагмент из мультфильма «Геройчики. Незваный гость», а также премьеры — «Синий трактор» и «Буба Шоу».

В выпуске:

Ми-ми-мишки
Серия: Призвание
Кеша разочаровывается в полезности своих изобретений и пытается найти своё «полезное» дело. В итоге Кеша убеждается в том, что то, чем он занимался раньше, и было его призванием.

Волшебная кухня
Серия: Шхомчхантхупс
Майя учит новую скороговорку и хочет рассказать её на Волшебной кухне. Хозяин волшебной кухни впечатляется способностями Майи и предлагает ей попробовать выговорить название адыгейского супа Шхомчхантхупс. Майя решает и попробовать его приготовить.

Кошечки-собачки
Серия: Игра
Мия и Алиса решили поиграть в студию красоты — но девочки обе хотели быть стилистами, а не посетителями. Тогда они решили поиграть в школу — но и здесь каждая из девочек хотела быть учительницей… Поиграть в доктора у подружек тоже не получается. Тогда девочки решают поиграть раздельно, раз уж у них не выходит играть вместе. Мия приходит к Дэну и Жоржику, которые заняты футбольными трюками. Она предлагает поиграть им в студию красоты — ребята соглашаются попробовать. Мия хотела заплести ребятам косы — но Дэн с Жоржиком захотели причёски, как у рок-музыкантов и стали играть на воображаемых гитарах. Мия попыталась поиграть с ними в доктора — но и тут игра пошла не по плану. Алиса же попыталась поиграть в школу с Максиком — но Максик превратил её в школу космонавтов. Расстроенные девочки пожалели о своей ссоре. Случайно встретившись на улице, девочки мирятся и с радостью соглашаются меняться ролями по очереди!

Синий трактор
Серия: Телефон
Синий трактор, Поливалка и Грузовик находят на детской площадке телефон. Они думают, что телефон игрушечный и решают поиграть с ним. Сначала они фотографируются, а потом решают попробовать позвонить кому-нибудь. Они открывают контакты и начинают звонить всем подряд, думая, что это игра. Очередь доходит до скорой помощи. Они звонят в скорую, говорят, что заболели, и через несколько минут приезжает настоящая машина скорой помощи. Ребята понимают, что телефон был не игрушкой, а самым настоящим.

Буба
Серия: Буба шоу – «Выпуск 1»
Буба Шоу — это весёлый и познавательный проект, в котором дети вместе с Бубой играют, смеются и учатся! Буба — наш любознательный и энергичный друг, который обожает пробовать новое. Пусть не всегда у него всё получается с первого раза, но его заразительный энтузиазм делает обучение увлекательным и весёлым!',
