'Мы все знаем, о чём произведение «Мёртвые души», слышали о ключевых персонажах поэмы — Коробочке, Собакевиче, Плюшкине. Но до сих мало, кто из нас знает ответ на ключевой вопрос, а кто такой Чичиков, каким человеком он был, о чем мечтал, в каких обстоятельствах рос и зачем собирал мёртвые души.

Спектакль «Мёртвые души» в режиссёрской постановке Ивана Комарова не пересказывает содержание поэмы. Режиссёр работает с контекстом поэмы, а рассказ в спектакле идёт от лица самого Гоголя. Будьте готовы, что вас ждёт абсолютно новое прочтение одного из самых гениальных произведений Николая Гоголя.

