('Олег Майами',
'https://afisha.yandex.ru/samara/concert/oleg-maiami-tour?source=rubric',
'Олег Майами — певец, шоумен. На каждом своём концерте он оставляет всего себя, раздавая бешеную энергетику, а зрители отвечают ему взаимностью. Совместные синглы «Не вспоминай» и «Громче города» с NILETTO и Лёшей Свиком стали настоящими хитами и попали в сердца миллионов слушателей, обеспечив исполнителям высокие строчки чартов и хит-парадов.

Летом Олег Майами и поп-король Филипп Киркоров выпустили совместный сингл «Стирай», и презентовали кинематографичный клип на этот трек, который всего за несколько дней собрал более 1 млн просмотров.

Ещё одной громкой совместной работой стал романтичный трек «Такси», который Олег Майами записал с Ольгой Бузовой.

Концерты Олега Майами — это всегда живой звук, невероятная энергия и харизма артиста, покорившая зрителей по всей России. «Не вспоминай», «Громче города», «Мельница», «Убегай», «Если ты со мной» — хиты, которые прозвучат со сцены на концерте Олега Майами.

Событие, которое нельзя пропустить! Будь громче города вместе с Олегом Майами!',
