'Stigmata едет в большой тур! Мы проведём год с вами на танцполах, где презентуем долгожданный большой релиз. С юга на север, с Камчатки и до Москвы. Заглянем даже в самые дальние и неочевидные города, потому что знаем, что вы ждёте встречи, чтобы угореть вместе с нами.

