('Раймонда',
'https://afisha.yandex.ru/samara/ballet/raimonda-samarskii-teatr-opery-i-baleta?source=rubric',
'Сценарий русско-французской писательницы и журналистки Лидии Александровны Пашковой основан на средневековой легенде о девушке, ожидающей из рыцарского похода своего возлюбленного. Средневековые сюжеты были очень популярны в России конца XIX века. Огромный интерес к той эпохе проявлял и композитор Александр Константинович Глазунов. Несмотря на работу над Шестой симфонией, он с большим энтузиазмом взялся за создание музыки к балету.

Мировая премьера «Раймонды» в постановке выдающегося балетмейстера Мариуса Петипа состоялась 7 января 1898 года в Мариинском театре. Для композитора Александра Константиновича Глазунова стала первым опытом обращения к жанру балета, а для Мариуса Петипа — последней большой работой.

В 1900 году балетмейстер Александр Алексеевич Горский совместно с Иваном Николаевичем Хлюстиным, взяв за основу хореографию Петипа, представил премьеру «Раймонды» в Большом театре, а в 1908 году он создал собственную оригинальную постановку балета.

В балете противопоставлены два мира: полный достоинства и рыцарского благородства мир Раймонды и варварский мир необузданных эмоций Абдерахмана и его свиты. Вторжение этого дикого, страстного начала в тихую жизнь романтичной девушки идеализированного Средневековья становится источником драматургического конфликта.',
