('Завтра была война',
'https://afisha.yandex.ru/samara/theatre_show/zavtra-byla-voyna-samarskiy-akademicheskiy-teatr-dramy-im-m-gorkogo?source=rubric',
'Герои спектакля не знают, что завтра будет война, что очень многим осталось жить считанные дни. Они упоенно воюют с учительницей, влюбляются, плачут и смеются, веселятся, дерутся, хулиганят и дерзят, но кажутся совсем еще детьми... Трагедия, случившаяся в классе, явилась, своего рода, проверкой готовности к завтрашним жертвам и завтрашним подвигам.

В спектакле звучат песни на стихи Павла Когана и Михаила Кульчицкого — молодых поэтов, погибших во время Великой Отечественной Войны в исполнении Игоря Скляра.',
