('Love Letters',
'https://afisha.yandex.ru/samara/theatre_show/love-letters-atele?source=rubric',
'Love Letters («Любовные письма») — спектакль о любви, понятно из названия. Есть двое, Он и Она. Они пишут друг другу письма. Пишут их всю жизнь.

Живая жизнь в словах. Рассказ ответом на рассказ. Откровенность на откровенность. История двух судеб, история любви. Они не вместе, и не по чьей-либо вине, — так вышло.

У каждого свой путь. Жизнь женщины и жизнь мужчины. Женщины талантливой, страстной, яркой, мужчины целеустремлённого, честного, умного. Итог любви — коробки писем.

Каждый сюжет в письме — повод прикоснуться к любимому человеку, рассказать эпизод из своей жизни, чтобы получить в ответ ещё немного слов. Слов любви.

Нет, письма не начинаются с «люблю» и не заканчиваются очередным признанием. Само письмо — свидетельство любви. Жить, зная, что есть тот или та, кому ты можешь рассказать свою жизнь во всех её нюансах, — уже большое счастье.

Love Letters — история любви с её возникновения, первых шагов, забавных и нелепых, с её радостью и открытиями, недоразумениями и обидами, страстями и сожалениями. Жизнь чувства.

Пьеса, написанная в середине прошлого века, сегодня стала по-новому созвучна времени. Герои истории писали письма и не рискнули «любовь в словах» превратить в «любовь земную». Расстояние от идеала до реальности оказалось непреодолимым. Сегодня такой сюжет назвали бы «виртуальным романом».

История, написанная тонко и умно, легко и изящно, давно стала классикой XX века. Её играли и играют лучшие актёры мировой сцены. Мы долго искали дуэт, такой, в котором встретятся страстная женственность и бескомпромиссная мужественность. И нашли.

В состав исполнителей могут быть внесены изменения без дополнительного уведомления.',
