'Комедия А.Н. Островского «Горячее сердце» — одна из самых веселых и озорных. Уморительно-смешные персонажи, остроумные диалоги, цветистая народная речь. Островский любит всех героев, он снисходителен даже к любителям горячительных напитков и — страшно сказать! — взяток. Разумеется, он бичует пороки, но любя. Ибо свое, родное, российское.

