('Женитьба Бальзаминова',
'https://afisha.yandex.ru/samara/theatre_show/zhenitba-balzaminova-samarskii-teatr-dramy-im-gorkogo?source=rubric',
'Великий русский драматург Александр Николаевич Островский хорошо разбирался в тонкостях человеческой души. Остроумный и ироничный текст его знаменитой пьесы давно разошёлся на цитаты, а брачная авантюра главного героя стала хрестоматийным примером брака по расчёту. Забавные ситуации, в которые попадает непутёвый Миша Бальзаминов, пытающийся найти богатую невесту, составляют сюжет одного из популярнейших произведений классической русской драматургии. Красочные костюмы и декорации Нины Юнгвальд-Хилькевич, неповторимая игра талантливых и замечательных артистов придадут дополнительный шарм лёгкой комедии Александра Островского в постановке Ирины Васильевой.

Спектакль подарит зрителям яркие эмоции, хорошее настроение и снова докажет, что судьба улыбается тем, кто верит в мечту.',
