'Спектакль «Метель» по бессмертной повести Александра Сергеевича Пушкина — это театрализованная фантазия, сплетающая в единое звучание эпохи начала XIX и XX веков: прозаический текст и романсы на стихи Пушкина, актерскую игру, вокал, музыку Георгия Свиридова в исполнении артистов оркестра и уникальное видео оформление.

