('Сказка о царе Салтане',
'https://afisha.yandex.ru/samara/theatre_show/skazka-o-tsare-saltane-samarskii-khudozhestvennyi-teatr?source=rubric',
'В основе сюжета — одно из самых известных произведений Александра Сергеевича Пушкина «Сказка о царе Салтане, о сыне его славном и могучем богатыре князе Гвидоне Салтановиче и о прекрасной царевне Лебеди». В постановке, выполненной в духе площадного представления скоморохов, сочетаются как динамичное действие, живой юмор, так и проникновенный лиризм, которые переносят зрителя в удивительный сказочный мир. А эпичность пушкинского слога в старинном духе причудливо обрамляют роскошные костюмы и стилизованное музыкальное оформление.',
