('Москва, Черёмушки',
'https://afisha.yandex.ru/samara/operetta/moskva-cheriomushki-samarskii-teatr-opery-i-baleta?source=rubric',
'Черёмушки, в Черёмушках черемуха цветет
И все мечты сбываются у тех, кто здесь живет.

Пусть Дмитрий Шостакович, чье имя теперь носит наш театр, и не писал ничего специально для Куйбышевского театра оперы и балета, но именно в Куйбышеве закончил свою легендарную Седьмую («Ленинградскую») симфонию и слушал ее первое исполнение в зале нашего театра. Шостакович хорошо известен как музыкант, писавший серьезные трагические произведения. Но мало кто знает, что важнейший российский композитор XX века не стеснялся любви к легкому жанру — оперетте, цыганскому пению, джазу.

Сюжет единственной оперетты, которую сочинил Шостакович — «Москва, Черемушки», — композитору предложили в 1958 году Владимир Масс и Михаил Червинский. Шостакович согласился и сопроводил бытовой, но авантюрный сюжет яркой, запоминающейся музыкой. За московской премьерой последовали спектакли в Ростове-на-Дону, Одессе, Свердловске, Братиславе, Праге, Магадане, Загребе, разных городах ГДР и Чехословакии. А через два года на основе оперетты был снят фильм «Черёмушки» (режиссер Герберт Раппапорт).

Основная тема оперетты перекликается с отечественной историей 1950-х–60-х годов. В ней рассказывается о масштабном переезде москвичей из коммунальных квартир в отдельные, собственные в новостройках. Не обходится и без смешных и трогательных ситуаций, сопутствующих этому «великому переселению».',
