('Семейка Аддамс',
'https://afisha.yandex.ru/samara/musical/semeika-addams-tiumenskii-dramaticheskii-teatr?source=rubric',
'Спектакль — лауреат Российской Национальной театральной премии «Золотая маска» в сезоне 2020-2021 годов в жанре «Оперетта/Мюзикл»

Спектакль — четырёхкратный лауреат Национального фестиваля и премии «Музыкальное сердце театра» в 2022 году.

Спектакль — участник фестивалей «Язык мира» (Красноярск,2022), «Другие берега» (Новосибирск,2022).

Спектакль вошёл в шорт-лист премии «Звезда театрала — 2022» в номинации «Лучший музыкальный спектакль».

Успех этого мюзикла, безусловно, в самой истории — сумасшедшая семейка Аддамс не может не полюбиться! Папа Аддамс любит долгие прогулки в ненастную погоду. Мама Аддамс считает, что чёрный цвет самый яркий. У детей, Венсдей и Пагсли Аддамсов, кладбище — любимая площадка для игр. Бабушка выпивает пару капель яда перед сном. Вы всё ещё думаете, что ваши родственники странные? Знакомьтесь — семейка Аддамс! И несмотря на свои образы — очень дружная семья. Они с удовольствием шутят, постоянно разыгрывают друг друга, и, кроме того, обладают некоторыми сверхъестественными способностями. Не семья, а просто праздник какой-то! Однако даже в этой очень дружной семейке Аддамс есть свои проблемы и скелеты в шкафу...

Мюзикл «Семейка Аддамс» — это история семьи, любви и дружбы. Это 23 музыкальных номера, живой вокал, оригинальная хореография, невероятная атмосфера, захватывающая история, юмор и шутки странной семейки!',
