'«Возвращение» — знаменитый рассказ русского классика ХХ века Андрея Платонова.

Он о любви и об измене. Можно ли любить, изменяя при этом, при известных обстоятельствах? А обстоятельства эти непростые — война. Она разрушила многие семьи. На фронте возникали военно-полевые романы, дома женщины от тоски бросались в чужие объятия. Можно ли простить или хотя бы понять? В эти непростые обстоятельства ставит своих героев Андрей Платонов. Как быть? Продолжать жить, закрыв дверь за своим прошлым, — говорит автор. Возвращаться.',
