'https://afisha.yandex.ru/samara/theatre_show/proshlym-letom-v-chulimske-teatr-dramy-kamernaia-stsena?source=rubric',
'Самый талантливый драматург «советского» периода 1960–70-х — Александр Вампилов погиб молодым, в 1972 году, не дожив двух дней до тридцати пяти и не узнав своей славы. Как это часто бывает, он стал знаменитым только после смерти. Теперь все театры ставят его пьесы, а когда-то отказывались их даже читать.

Слишком уж странным, пугающе- «несоветским» был в них главный герой, совсем не передовик производства, а, напротив, асоциальный персонаж, у которого «в душе пусто, как в графине алкоголика», «все израсходовано, раскидано, растеряно, в груди, будто в печной трубе, воет ветер». Конечно, Вампилов выводил на сцену подобного персонажа из духа протеста против эпохи застоя и безвременья.

Но сегодня, через 50 лет, нас в его пьесах привлекает иное и многое видится иным. Каждый театр слышит в многоголосии Вампилова свою тему, потому и спектакли у всех разные.

В маленьком таежном городке живут такие узнаваемые, близкие и понятные нам персонажи. Они совсем не безупречного поведения, могут и лишнюю рюмку опрокинуть, и в драку полезть, и дико ревновать, и совершать дурацкие поступки. Но нам понятны их мотивы, мы сами такие.

И еще в жизни каждого из нас случается день, не такой, как обычно, когда все представляется в фантастическом свете, иллюзия видится явью, счастье кажется таким близким, ине хочется верить, что этот день пройдет, ничто более не повторится: ни первая любовь, ни время, ни эпоха.',
