'https://afisha.yandex.ru/samara/theatre_show/geroi-nashego-vremeni-samarskii-teatr-dramy-im-gorkogo?source=rubric',
'Печорин — самая загадочная фигура русской литературы.

Исследование человека и человечества глазами сверхчеловека Печорина составляет суть путешествия, в которое отправляет нас великий русский писатель Михаил Лермонтов.

Печорин — персонаж, родственный лермонтовскому Демону. Познав в раннем возрасте, подобно самому Лермонтову, все мотивации человеческих поступков, Печорин считывает их, как детскую книгу, легко предугадывая цель и результаты людских деяний. Скука и предсказуемость, недальновидность и невысокость людских намерений составляют печаль Печорина, как и печаль лермонтовского Демона.

Авторский пессимизм, однако, не мешает быть Лермонтову захватывающим в описании человеческих страстей, интриг, влюблённостей, благородных и неблагородных чувств. Даже война у него — лишь попутный красивый фон, на котором развивается человеческая комедия. Как и кавказские пейзажи, придающие всему действию мрачноватую, но обворожительную привлекательность.

Ущелья и отвесные скалы — важный антураж жестоких игр Печорина. А минеральные воды, которые пьют курортники, утешая себя надеждой на их целительность, знак лермонтовской насмешки над химерами людских упований. Ведь человечество, как считал писатель-мизантроп, неисцелимо.

Спектакль «Герой нашего времени» расскажет зрителям, кто же такой Печорин, почему ему «и скучно, и грустно», за что его все любят, а он — никого. Герой, который когда-то испытывал чувства, надеялся на счастье, любил, но всё потерял.

С антрактом

Внимание! В спектакле содержатся сцены демонстрации и курения табачных изделий.

