'Спектакль-дуэль между женщиной любящей и женщиной любимой.

Вы любите стихи? Или вы их не любите, боитесь не понять и заскучать? Вы думаете, что всё знаете про любовь? Разорвите шаблоны! Это будет неожиданно! Откровенно! Ярко и красиво! Стильный, тонкий, душевный спектакль удивит, поразит, восхитит и подарит праздничное настроение! А игра актрис не оставит вас равнодушными!',
