('Зори здесь тихие',
'https://afisha.yandex.ru/samara/musical-play/zori-zdes-tikhie-samarskii-teatr-opery-i-baleta?source=rubric',
'К 80-летию Великой Победы — премьера музыкальной драмы «Зори здесь тихие...».

В год 80-летия Победы в Великой Отечественной войне Самарский академический театр оперы и балета им. Шостаковича представляет премьеру спектакля Кирилла Молчанова «Зори здесь тихие...» по знаменитой повести Бориса Васильева.

Спектакль, впервые поставленный в Большом театре в 1973 году, вновь оживает на самарской сцене. Это трагическая история о подвиге девушек-зенитчиц, основанная на реальных событиях, никого не оставляет равнодушным. Повесть Бориса Васильева, получившая всенародное
признание, была блистательно экранизирована Станиславом Ростоцким в 1972 году. Именно Кирилл Молчанов, автор музыки к фильму, впоследствии создал одноименный спектакль, написав и либретто.

Постановка спектакля осуществлена творческой командой студентов и выпускников ГИТИСа.

Спектакль создан при поддержке Российского института театрального искусства — ГИТИС',
