'2025-05-09 00:00:00',
232),
('На дне.doc',
'https://afisha.yandex.ru/samara/theatre_show/na-dne-doc?source=rubric',
'Документальный спектакль подразумевает, что в основе постановки лежит не художественное произведение, а реальный документ. Таким документом могут быть переписка в мессенджере, юридические бумаги, фотография или реальный разговор, услышанный в баре. Из подобных разговоров и строится спектакль. В январе 2024 года режиссер Дмитрий Крестьянкин общался с жителями Самары в разных барах, в том числе и легендарном «На Дне», в честь которого спектакль получил свое название. Из этих разговоров сложилась пьеса.
​
Спектакль «На дне.doc» — это попытка понять культурный код Самары, поделиться переживаниями о любви, поразмышлять о космосе, поболеть за «Крылья Советов» и понять, что реализм в театре — это очень опасно. Бар — это место встреч, место совместного переживания радостных и горестных событий, место честных разговоров, которые часто невозможны в иных ситуациях.',
'от 2 000 ₽',
'https://avatars.mds.yandex.net/get-afishanew/5109582/ee369db6524c407b86f1e1543d78cbd6/s760x440',
1154202497291966506,
'2025-05-14 00:00:00',
233),
('По дороге к страусам',
'https://afisha.yandex.ru/samara/theatre_show/po-doroge-k-strausam?source=rubric',
'Виктор Розов был очень популярен в 60-70 е годы прошлого века, а сегодня о писателях - «шестидесятниках» почти забыли. Но постепенно в обществе стал возникать интерес к драматургии середины века, к героям-романтикам, верившим в добро и справедливость. Все устали от «чернухи», от персонажей, испытывающих отвращение к жизни и выплескивающих это отвращение со сцены и экрана на ни в чем не повинных зрителей.

Герой спектакля «По дороге к страусам» (по пьесе «В дороге») - совсем молодой человек, только что окончивший школу. Он пока сам не знает, чего хочет, но точно знает, чего не приемлет в жизни, что ненавидит. Это представитель «рассерженного поколения». Оказавшись в дороге без копейки денег, он встречает самых разных людей - и плохих, и хороших, и, конечно, - свою любовь.

Театр не отказал себе в удовольствии вспомнить атмосферу 60-х — с ее стилягами и работягами, задушевными песнями, популярными телепередачами и «Голубыми огоньками».',
