('Сильва',
'https://afisha.yandex.ru/samara/operetta/silva-samarskii-akademicheskii-teatr-opery-i-baleta?source=rubric',
'Имре Кальман один из основоположников и наиболее видных представителей новой венской оперетты, отличающейся остротой сюжетных ситуаций, развернутой музыкальной драматургией, эффективной оркестровкой. Его искусство обладает не только щедрым мелодическим даром, но и способностью психологически тонко обрисовать внутренний мир героев.

Оперетта Имре Кальмана «Сильва» известна и под другими названиями: «Королева чардаша», «Княгиня чардаша». Сюжет её — «театр о театре», рассказ о судьбе артистки варьете. Окружение Сильвы — князья, графы. Ее талантом восхищаются, но влюбленный в Сильву Эдвин, сын князя Воляпюк, из-за сословных предрассудков не может на ней жениться. Переплетаются судьбы героев, и постепенно становится ясно, как обманчиво многое в их жизни… «Сильва» — была, есть и всегда будет опереттой номер один, ее вдохновенные мелодии рассказывают о всепобеждающей силе любви, которой не страшны никакие преграды.',
