('Фредерик, или Бульвар преступлений',
'https://afisha.yandex.ru/samara/theatre_show/frederik-ili-bulvar-prestuplenii-samarskii-teatr-dramy-im-gorkogo?source=rubric',
'Постановка по блестящей комедии французского драматурга Эрика-Эмманюэля Шмитта перенесёт зрителей во Францию начала XIX века. В ней неразрывно соединились театр и жизнь, как два полюса одного целого. Спектакль открывает завесу тайн актерских судеб, дает прикоснуться зрителям к прозе и лирике актёрской жизни. Великого актера позапрошлого века Фредерика Леметра играет любимец публики — заслуженный артист России, лауреат Национальной театральной премии «Золотая маска» Владимир Гальченко.',
