('Женский форум',
'https://afisha.yandex.ru/samara/standup/zhenskiy-forum-2025-05?source=rubric',
'«Женский Форум» — шоу, в котором девушки дают советы по любым жизненным вопросам, хотя их об этом никто не просил.

Варвара Щербакова, Александра Муратова, Ольга Парфенюк и Наталья Борисова разберут запросы пользователей с реального женского форума и прокомментируют их, подкрепляя это историями из своей жизни.

