'https://afisha.yandex.ru/samara/opera/tsarskaia-nevesta-samarskii-akademicheskii-teatr-opery-i-baleta?source=rubric',
'В основу драмы Мея положен исторический (хотя и малоизвестный) эпизод женитьбы (в третий раз) царя Ивана Грозного. Вот что рассказывает об этой истории Карамзин в своей «Истории Государства Российского».

«Скучая вдовством хотя и не целомудренным, Иван Грозный уже давно искал себе третьей супруги... Из всех городов свезли невест в Слободу, и знатных и незнатных, числом более двух тысяч: каждую представляли ему особенно. Сперва он выбрал 24, а после 12... долго сравнивал их в красоте, в приятностях, в уме; наконец предпочел всем Марфу Васильеву Собакину, дочь купца новгородского. Но царская невеста занемогла, начала худеть, сохнуть: сказали, что она испорчена злодеями, ненавистниками Иоаннова семейного благополучия. Злобный клеветник, доктор Елисей Бомелий, предложил царю истреблять лиходеев ядом и составлял, как уверяют, губительное зелье с таким адским искусством, что отравляемый издыхал в назначенную тираном минуту. Так Иоанн казнил одного из своих любимцев Григория Грязного, князя Ивана Гвоздева-Ростовского и многих других, признанных участниками в отравлении царской невесты.

Между тем царь женился на больной Марфе, надеясь, по eгo собственным словам, спасти ее сим действием любви и доверенности к милости Божией; через шесть дней женил и сына на Евдокии Сабуровой, но свадебные пиры закончились похоронами: Марфа 13 ноября скончалась, быв или действительно жертвою человеческой злобы, или только несчастною виновницею казни безвинных».

