'Странный народ эти взрослые... Погрязают в расчётах, власти, тщеславии, вредных привычках или просто утомительном напрасном труде, и считают, что это главное. Маленький принц, дитя с другой планеты, знает: зорко одно лишь сердце. У него есть искренняя любовь, крепкая дружба и ответственность за родную землю — по-настоящему самое важное в жизни. Новая постановка Яны Миносян по философской сказке Антуана де Сент-Экзюпери побуждает посмотреть на мир глазами ребёнка и сделать удивительные открытия в привычных вещах. «Ведь все взрослые сначала были детьми, только мало кто из них об этом помнит».',
