('Страдания юного Вертера',
'https://afisha.yandex.ru/samara/theatre_show/stradaniia-iunogo-vertera?source=rubric',
'Книгу «Страдания юного Вертера» обожал Наполеон, она оказала огромное влияние на всю последующую мировую литературу. Написанный два с половиной века назад , роман очень современен.

Главный герой — Вертер, он конфликтует с миром расчётливых, ко всему равнодушных людей, которые довольствуются «скотским благополучием» (говоря словами Мандельштама).

В спектакле «Камерной сцены» Вертер — художник, картины которого не понимают. Но он и сам не понимает многого, например, того, почему его любимая девушка Лотта, которая отвечает ему взаимностью, выходит замуж не за него, а за успешного молодого человека. Сегодня никому и в голову бы не пришло удивляться такому её поступку. Пылкое, страстное, бескомпромиссное существование в наш прагматичный век вызывает у многих молодых ироническую усмешку.

С Лоттой связана основная проблема спектакля — истинных и ложных ценностей, проблема выбора, от которого зависит жизнь человека. Отказавшись от сумасшедшего художника Вертера, Лотта приобретает лишь унылую стабильность. Исчезает поэзия, остаётся грустный реализм.

Неизвестно, стал бы Наполеон Наполеоном, если бы не прочитал эту книгу.',
