('Мой папа — Питер Пэн',
'https://afisha.yandex.ru/samara/theatre_show/moi-papa-piter-pen-samarskii-teatr-gorod?source=rubric',
'Папа семилетнего Дани – безработный актер. Он бесконечно обаятелен и беспечен, и пока мама Дани работает на трех работах, папа то забывает дать сыну бутерброд, то отправляет в школу в пижамных штанах с овечками. Над Даней смеются. «Лучше бы у меня был какой-нибудь другой папа!» – в сердцах восклицает мальчик, и тогда отец открывает ему тайну. Он, папа, на самом деле – Питер Пэн. Он только выглядит взрослым, потому что так удобнее. Маленький Даня в восторге. Находятся ответы на все вопросы – куда папа иногда исчезает (конечно, путешествует на остров Нетинебудет), почему ведет себя так странно (он же мальчик в теле дяденьки) и не зарабатывает достаточно денег (что для Питера Пэна деньги!). Почему так сердится мама (она, конечно же, Венди, просто выросла и, скажем так, испортилась).',
