('Пламя Победы',
'https://afisha.yandex.ru/samara/ballet/plamia-pobedy-samarskii-teatr-opery-i-baleta?source=rubric',
'Самарский академический театр оперы и балета им. Шостаковича с гордостью представляет программу «Пламя Победы», посвящённую 80-летию Победы в Великой Отечественной войне. В рамках этого уникального вечера зрители смогут увидеть два одноактных балета: «Ленинградскую симфонию» на музыку Дмитрия Шостаковича и «Дом у дороги» на музыку Валерия Гаврилина (премьера!).

«Ленинградская симфония» — это масштабное полотно, эпическое повествование о мужестве и героизме осажденного Ленинграда. Либретто и хореографию одноактного балета, основанного на первой части Седьмой «Ленинградской» симфонии Шостаковича, создал в 1961 году Игорь Бельский. Этот балет погружает зрителей в атмосферу исторической драмы, подчеркивая стойкость и единство народа в тяжелые времена.

Одноактный балет «Дом у дороги» на музыку Валерия Гаврилина и либретто Дмитрия Антипова, основанном на одноименной поэме Александра Твардовского, рассказывает камерную историю, разворачивающуюся на фоне всеобщей трагедии. Здесь война предстает глазами отдельной семьи, акцентируя личные потери, страдания и боль.

Оба балета, несмотря на разный масштаб и хореографический язык, говорят об одном и том же — о войне как о страшном, бесчеловечном явлении, оставляющем неизгладимый след в судьбах людей. Они заставляют задуматься о цене мира, ценности человеческой жизни и о необходимости помнить уроки истории.

Не упустите возможность стать частью этого значимого события и проникнуться духом памяти и уважения к тем, кто сражался за свободу и мир!',
'от 300 ₽',
'https://avatars.mds.yandex.net/get-afishanew/5098259/b204853fe98c7a8c49a606f5fbaf6ced/s760x440',
8963580829962683892,
'2025-05-03 00:00:00',
253),
('Пугачёв',
'https://afisha.yandex.ru/samara/theatre_show/pugachev-tiumenskii-dramaticheskii-teatr?source=rubric',
'Историческая музыкальная драма в двух действиях.

Пьеса Ольги Погодиной-Кузминой по мотивам повести А. С. Пушкина «Капитанская дочка».

«Предать молчанию и забвению» само имя Емельяна Пугачёва и вычеркнуть страшный бунт из русской истории — так повелела императрица Екатерина II. И приказ был исполнен — на долгие годы свидетельства и документы о масштабном восстании 1773–1775 годов были надежно спрятаны в архивах и засекречены.

Даже Пушкин не получил доступа к протоколам допросов пугачевских соратников. Он исследовал отголоски бунта спустя 60 лет, когда в окрестностях Оренбурга ещё живы были свидетели трагических событий и прямые их потомки. Их рассказы, а также разрозненные письма, указы и воззвания послужили основой для истории молодого офицера Петра Гринёва, его соперника Алексея Швабрина и его невесты Марии Мироновой.

Переосмысляя пушкинскую повесть, дополняя историческим контекстом и архивными источниками, авторы спектакля «Пугачёв» задаются вопросами о причинах и последствиях «беспощадного русского бунта». Музыкальные номера, спецэффекты, визуальные парадоксы по-новому открывают знакомый сюжет, в котором каждый найдет ответы на вечные вопросы о добре и зле, и перекличку с сегодняшним днём.

«Пугачёв» — это яркий, фантастический, немного безумный образ, воплотивший русскую душу во всём её противоречии.',
