('Carmina Burana',
'https://afisha.yandex.ru/samara/opera/carmina-burana-donetskii-teatr-opery-i-baleta?source=rubric',
'Первое исполнение сценической кантаты Carmina Burana состоялось 8 июня 1937 года в Старой опере Франкфурта-на-Майне.

Carmina Burana переводится с латыни как «Бойернские песни» (этот сборник средневековой поэзии был найден в 1803 году в бенедиктинском монастыре Бойерн). Для либретто было выбрано 24 стихотворения на латинском и средневерхненемецком языке.

Беспощадная Фортуна циклично обрушивает на людей несчастья. На этом фоне разворачивается непростая история любви Поэта и Девушки. Есть риск погубить себя в беззаботном веселье и удовольствиях — спасает целительная сила поэзии. Фортуна же снова являет свою мощь. Но остается надежда...',
