('Праведник',
'https://afisha.yandex.ru/samara/cinema/pravednik-2022?source=rubric',
'1942 год. Офицер Красной Армии Николай Киселёв получает приказ вывести с оккупированных белорусских земель за линию фронта свыше двухсот евреев — стариков, женщин и детей, чудом избежавших неминуемой жестокой расправы. Этим истощённым, измученным голодом и страхом людям, потерявшим родных и едва не сошедшим с ума от пережитого ужаса, предстоит пройти пешком по лесным тропам сотни километров, чтобы вновь обрести надежду на спасение и веру в будущее.

В основе фильма – бессмертный подвиг Николая Киселёва, офицера Красной Армии, который в августе-октябре 1942 года спас 218 советских евреев, выведя женщин, стариков и детей из фашистской оккупации за линию фронта. Отряд из пяти бойцов-партизан во главе с Киселёвым на протяжении почти 1500 км вёл по лесам изнурённых и голодных людей, преследуемых немцами. В 2005 году израильский Международный институт по изучению Холокоста Яд Вашем присвоил Николаю Киселёву звание Праведник народов мира, его имя занесено на стену почёта в Саду праведников. Потомки спасённых людей ежегодно собираются в Тель-Авиве, чтобы почтить его память. В основе сценария – подлинные рассказы участников драматических событий и их родственников.',
