('Bodyscope Film Festival: французская программа',
'https://afisha.yandex.ru/samara/cinema/bodyscope-film-festival-france-2025?source=rubric',
'Семь фильмов молодых французских режиссёров и хореографов. От освободительного гимна сестринству молодой звезды французской сцены Лейлы Ка через гипнотическое путешествие в мир Ива Кляйна в хореографии Лоана Жако до подводных танцев Марин Шене, которая учится новым принципам движения у горбатых китов — каждая кинокартина вдохновит зрителей на размышления о связи человека и окружающего мира.

В программе:

«Неравный старт»
Лейла Ка · Жоселин Карре · 15 минут · Франция · 2024
Одиннадцать женщин со своими взглядами на мир. Каждая с цветами на платье и печалью в глазах, как результатом их места в обществе. Вместе, без слов, они решают освободить себя. Начинается коллективное движение.

«Чувствительность»
Аксель Шеман · 8 минут · Франция · 2024
«В сердце пустоты, как и в сердце человека, горят огни». Этот симбиоз танца и других медиа приглашает нас совершить чувственное гипнотическое путешествие в мир произведений Ива Кляйна.

«Ты достаточно хорош»
Лиза Маньон · 11 минут · Франция · 2022
Фильм разворачивается в чистом белом пространстве через взаимодействие четырёх героев. Делая видимыми несовершенства и поощряя принятие себя, эта рассказанная с юмором история углубляется в темы идентичности, разнообразия и индивидуальности.

«Болеро»
Мехди Керкуш · 4 минуты · Франция · 2025
«Болеро» Равеля благодаря своей универсальности и заразительной энергии выходит за рамки поколений и культур. Созданный для танца, он продолжает вдохновлять артистов. Мехди Керкуш представляет нам свою версию Болеро, инклюзивную визуальную вселенную, сотканную из удивительных сплетений танца, музыки и кино в разных локациях французского города Кретей.

«Жизнь на пороге»
Венсан Бруно · Марин Шесне · 29 минут · Франция · 2022
Марин Шеcне, хореограф и современная танцовщица, отправляется на остров Реюньон, чтобы встретиться с горбатыми китами. Из этих взаимодействий в море родились танцевальные импровизации, которые станут плодородной почвой для её следующего творения.
Этот фильм, снятый на задержке дыхания, представляет собой хореографическое путешествие под водой и на поверхности по следам встреч с диким животным в его естественной среде обитания.
«Жизнь на пороге» задаётся вопросом о том, что происходит внутри нас в этом пространстве отношений, где мы не можем ничего контролировать — кроме нашей открытости тому, что может произойти, — и ставит под сомнение наш способ проживания жизни.

«Сезоны танца — лето»
Томми Паскаль · 12 минут · Бельгия · Франция · Германия · 2025
Лето — один из четырёх эпизодов кинематографической сюиты «Сезоны танца», срежиссированной Томми Паскалем на музыку Макса Рихтера «Новые Времена года» (рекомпозиция Антонио Вивальди) в хореографии Бобби Джейн Смит и Ора Шрайбера. Чувственный обмен между хореографией, музыкой, природой и камерой.
Ор Шрайбер: «Когда мы стали делать летний сезон, то присоединили к нему слово „страсть“. Это было очевидно, потому что наша работа затрагивает множество тем, связанных с любовью. Кажется, это очень хорошо соответствует тому, кем мы являемся».
Бобби Джейн Смит: «Когда мы разрабатывали „Лето“, мы захотели начать с трёх разных движений: это стало исследованием того, что для нас значит страсть, укоренённое в повседневных жестах между двумя людьми за столом, в ситуации, которая всем известна. Мы решили посмотреть, как мы можем раздвинуть границы взгляда на то, что открыто, и что скрыто».

«Убежище»
Жереми Бульон · 5 минут · Франция · 2022
Свет и тень показывают, как существа исследуют окружающую среду. Оглушённые металлическим эхом, они собираются в стаю, проявляя уязвимость, свойственную людям. Находясь между контролем равновесия и падением, их тела устремляются в неистовую гонку.

О фестивале

Международный фестиваль пластического кино Bodyscope Dance Film Festival — это единственный в России международный кинофестиваль короткометражных пластических фильмов.

За 6 лет существования Bodyscope Dance Film Festival превратился в крупный международный фестиваль, который объединяет авторов и поклонников кинотанца. Цель фестиваля — дать возможность режиссёрам и хореографам со всего мира показать свои работы на большом экране в разных городах России и популяризировать кинотанец, сделать его доступным широкому зрителю.

Программа фестиваля состоит из международных конкурсных и внеконкурсных показов, которые пройдут в Москве, Санкт-Петербурге, Новосибирске, Кирове, Нижнем Новгороде и Самаре с 25 по 27 апреля 2025. На фестивале представлены фильмы как именитых авторов, призёров Берлинале и кинофестиваля в Локарно, так и начинающих режиссёров и хореографов.',
