'…Детство 12-летнего Ивана закончилось в тот день, когда у него на глазах фашисты расстреляли мать и сестрёнку. Отец мальчика погиб на фронте. Оставшись сиротой, Иван уходит в воинскую часть и становится неуловимым разведчиком. Он с риском для жизни добывает для командования бесценные сведения о противнике. Но война есть война…

