('TheatreHD: Дзеффирелли: Травиата',
'https://afisha.yandex.ru/samara/cinema/traviata-1982?source=rubric',
'Дзеффирелли не пожалел средств на роскошные исторические декорации, чтобы чувственно и элегантно воссоздать историю счастья и падения Виолетты Валери.

Непревзойдённое музыкальное качество постановки гарантируют ведущие музыканты мира: оркестр Метрополитен-оперы, дирижёр Джеймс Ливайн, певцы Тереза ​​Стратас и Пласидо Доминго. В роли Виолетты Тереза ​​Стратас находит удивительно точный баланс между эмоциональным величием и физической слабостью. Со всей страстью воплощает Альфреда Жермона и Пласидо Доминго со своим трогательно-лирическим тембром и магнетическим актёрским мастерством.

В постановке заняты и звёзды Большого театра — Екатерина Максимова и Владимир Васильев в роли испанских танцоров на балу.

Париж, около 1850 г. Больную чахоткой куртизанку Виолетту Валери полюбил юный Альфредо, но Виолетта боится полностью посвятить себя ему. После нескольких месяцев совместной жизни к ней является отец Альфреда, Жорж Жермон, и просит Виолетту разорвать скандальную связь, угрожающую браку его дочери. Виолетта неохотно соглашается. После её отъезда Альфред находит письмо с сообщением, что им необходимо расстаться. Альфред отправляется на бал, который устраивает Флора, подруга Виолетты, и видит там свою возлюбленную в обществе бывшего воздыхателя, барона Дюфоля. Взбешённый Альфред швыряет ей в лицо деньги в знак того, что полностью расплатился с ней. Через несколько недель болезнь Виолетты обостряется. Жермон в письме к ней сообщает, что рассказал сыну о принесённой ею жертве. Альфред спешит к любимой и умоляет о прощении. Виолетта последним усилием встаёт на ноги, но умирает на руках у Альфреда.

«Конечно, главное здесь — сюжет и музыка, но нам повезло заполучить в фильм двух лучших оперных артистов современности. Пласидо Доминго как актёр не менее талантлив, чем как певец, и, наверное, все согласятся, что Тереза Стратас — самая выразительная актриса и сопрано на оперной сцене. Для успеха фильма в США нужно и то, и другое, и у нас есть всё это». – Дзеффирелли в интервью журналу «Variety».

«Если кто-то и способен сделать оперу доступной для всех, это Франко Дзеффирелли. Если благодаря ему мои родители пойдут на “Травиату” или на любую другую оперу, которую они раньше не видели, то все мои усилия на этой картине были не зря». – Тереза Стратас в интервью журналу «Variety».

«Как и можно было ожидать, киноверсия “Травиаты” от Франко Дзеффирелли — отменно роскошное зрелище, карнавал красок и текстур. […] Стратас удаётся достичь нужного баланса между величием духа и физической слабостью… Доминго играет Альфредо опытным мужчиной, человека, который, попробовав в этой жизни всё, впервые встречает свою настоящую любовь.» («Variety», 15.12.1982)

Награды и фестивали:
Номинация на премию «Оскар» (1983) – лучшие декорации, лучшие костюмы
Премия BAFTA (1984) – лучшая работа художника-постановщика, лучшие костюмы
Премия Nastro d&#39;argento – лучшие костюм, лучшие декорации, лучшая операторская работа
Номинация на премию «Золотой глобус» (1983) – лучший иностранный фильм',
