('Дзеффирелли: Богема',
'https://afisha.yandex.ru/samara/cinema/bogema-1965?source=rubric',
'В 1965 году кино- и театральный режиссёр Франко Дзеффирелли снял свою первую экранизацию оперного произведения — «Богему», легендарный фильм, который во многом способствовал популярности оперы Пуччини сегодня.

Невероятно драматичное произведение бросает вызов мнению, что опера не очень кинематографична. Дзеффирелли ставил эту пронзительную зимнюю историю на сцене миланской «Ла Скала», оценил заложенный в ней кинотенциал и виртуозно адаптировал для большого экрана, снимая в студии и делая ставку на крупные планы.

Легендарная экранизация по праву считается одной из величайших кинематографических адаптаций оперы всех времён.

Эта постановка «Богемы» стала первой сразу во многих отношениях: первый фильм-опера, выпущенный Unitel; первый музыкальный фильм с Гербертом фон Караяном в качестве дирижёра; первая масштабная кинокартина режиссёра Франко Дзеффирелли.

«Богема» вышла на экраны в 1965 году, основой для неё послужил оперный спектакль из Ла Скала. Главные роли злосчастных влюблённых исполнили Мирелла Френи и Джанни Раймонди, оркестром и хором театра Ла Скала руководит Герберт фон Караян. Этот фильм-спектакль до сих пор считается одним из лучших воплощений оперы на киноэкране и входит в золотой фонд оперных постановок XX века.',
