'Мать тоскует о молодости, когда была окружена поклонниками и комфортом, вспоминает бросившего её мужа и срывается на детях. Сын мечтает о творчестве, а вынужден кормить семью, работая на фабрике. Дочь, ставшая инвалидом из-за пережитой в детстве болезни, замкнута, застенчива и неуклюжа и может лишь мечтать о возможности танцевать и любить. Тоску замученной бытом и неустроенностью семьи разрушает визит молодого человека — школьного приятеля сына.',
