('Западня',
'https://afisha.yandex.ru/samara/cinema/zapadnya-2025?source=rubric',
'Этот вечер для Эдди сразу не задался: он решил угнать не ту машину. И владелец роскошного автомобиля Уильям взял закон в свои руки. Теперь Эдди в плену очень опасного человека и, если он не придумает, как ослабить мёртвую хватку самопровозглашённого линчевателя, жить ему останется совсем недолго. Начинается жестокая игра в кошки-мышки, кульминация которой произойдёт в самом центре Лос-Анджелеса.',
