('О любви и дружбе',
'https://afisha.yandex.ru/samara/theatre_show/o-liubvi-i-druzhbe?source=rubric',
'За основу были взяты три пьесы известных драматургов: Евгения Гришковца, Людмилы Петрушевской, Семёна Злотникова.

Это три пьесы — три модели взаимоотношений между людьми, которые невероятным образом воплощают в себе все остроугольные моменты и ситуации семейной жизни, без преувеличения — каждой семьи нашей страны.

Это, действительно, наша история, это про нас, а потому, становится и интересно, и странно, и смешно!

Не секрет, что самое интересное на сцене театра — это человеческие взаимоотношения. Герои спектакля «О любви и дружбе» готовы продемонстрировать зрителям привычные и хорошо знакомые каждому модели отношений. Все они, такие непохожие в частностях, неизменно сходятся на личном одиночестве и непрерывном ожидании долгожданной второй половины.

Поиски счастья иногда смешны, порой — трагичны, но всегда наполнены простой потребностью человека верить, надеяться и любить! Именно поэтому спектакль «О любви и дружбе» — это история, которая хорошо знакома и близка каждому!

Спектакль идёт без антракта.

В составе исполнителей возможны изменения без дополнительного уведомления.',
