'https://afisha.yandex.ru/samara/standup/kosmicheskii-stendap-zhenskoe-shou-2025-4?source=rubric',
'Лучшие девушки комики во вселенной соберутся на сцене боулинг-ресторана Brooklyn Bowl, чтобы ты сногсшибательно провел этот вечер и увидел популярный формат шоу вживую!

Для тебя выступят звездные гостьи из Москвы и Питера:
— Надежда Ангарская, актриса и звезда шоу Comedy Woman
— Динара Курбанова, та самая, обладательница самого ангельского голоса в стендапе
— Кристина Ганина, актриса и участница шоу Женский стендап на ТНТ
— Таня Виноградова — ведущий резидент проекта StandupConcert

Brooklyn Bowl — это абсолютно новый формат отдыха и развлечения в твоем городе.

Авторские кухня и бар помогут насладиться вечером по полной!

Сбор гостей за час до начала программы.

Продолжительность шоу 90 минут.

Обратите внимание, что столы продаются по местам. Если хотите сидеть без подсадки, то нужно выкупать стол целиком.

Мероприятие 18+, на входе будут проверять паспорт.',
