('Щелкунчик',
'https://afisha.yandex.ru/samara/ballet/shchelkunchik-samarskii-teatr-opery-i-baleta?source=rubric',
'Пётр Ильич Чайковский (1840-1893).
Балет-феерия в двух действиях, трёх картинах с прологом и эпилогом.
Либретто Мариуса Петипа (1818-1910) по мотивам сказки Александра Дюма (1802-1870) «История Щелкунчика» (1844).
Хореография Льва Иванова (1892).

На сцене будет представлена премьера эксклюзивной редакции «Щелкунчика»: художественный руководитель балета театра, заслуженный артист России Юрий Бурлака воссоздал образ оригинальной постановки 1892 года, которая состоялась на сцене Мариинского театра. Именно в таком визуальном и хореографическом решении видел «Щелкунчика» на премьере сам Чайковский.

Зрители с нетерпением ждут встречи с самым волшебным новогодним балетом «Щелкунчик». Каждый год они погружаются в мир прекрасных детских грёз, переживая историю Клары и Щелкунчика.

Продолжительность: 2 часа 20 мин',
