('Женщины',
'https://afisha.yandex.ru/samara/immersive-theatre/zhenshchiny-teatr-daniila-mironova?source=rubric',
'Женщины. Лидия Вэнс.

Спектакль по мотивам произведения Чарльза Буковски «Женщины»
Спектакль строго 18+. Присутствует ненормативная лексика.

Спектакль о жизни главного героя Генри Чинаски и его многочисленных отношениях с женщинами.

Сюжет строится вокруг любовных похождений героя, которые варьируются от мимолетных интрижек до серьезных романов.

Роман отличается откровенным описанием сексуальной жизни героя, его борьбы с одиночеством и пристрастием к алкоголю. Чинаски воспринимает женщин зачастую негативно, считая их хищными и заинтересованными только в деньгах.

В произведении переплетаются автобиографические элементы и художественный вымысел, создавая яркую картину жизни и любовных приключений главного героя.',
