('Кошкин дом',
'https://afisha.yandex.ru/samara/musical-play/koshkin-dom-samarskaia-gorod?source=rubric',
'«Кошкин дом» — одна из лучших сказок XX века, любимая многими поколениями детей в стране. Живая, захватывающая, то смешная, то грустная пьеса Маршака с удивительными, одновременно реалистичными и сказочными иллюстрациями актеров театра «Город» — само совершенство! Тот, кто хоть раз смотрел этот спектакль, не забудет его уже никогда!

Сюжет прост, изящен и с большим юмором. В богатом доме Кошки случился пожар. Оставшись без крыши над головой, несчастная Кошка и ее дворник кот Василий идут просить приюта у своих друзей, которые были у них в гостях накануне. Однако ни Курица, ни Коза, ни Свинья не пускают Кошку переночевать. Только бедные племянники, котята-сироты, которым тетя Кошка отказывала даже в куске хлеба, открывают ей дверь своей нищей избушки. Финал, как и положено в детской сказке, — счастливый. Готов новый «пряничный», расписной васнецовский домик, ярко светит в небе солнце, Кошка и котята водят хоровод.

В составе исполнителей возможны изменения без дополнительного уведомления.',
