('Нурлан Сабуров',
'https://afisha.yandex.ru/samara/standup/nurlan-saburov-kontekst?source=rubric',
'Серьёзное лицо, обаяние, резкость и какая-то непривычная нам прямота, обескураживающая в начале, но совершенно точно очаровывающая каждого зрителя в зале. Тонкая грань юмора, где явно не захочется обвинить комика в оскорблении чувств кого бы то ни было. Нурлан делает это с таким изяществом и превосходством, что единственное, что остается зрителю — восхититься, расслабиться и посмеяться от души. Окаменеть от бесстрастности монологов и ожить от элегантной искренности — в этом вся суть выступлений Нурлана Сабурова.',
