('Незамужняя женщина',
'https://afisha.yandex.ru/samara/theatre_show/nezamuzhniaia-zhenshchina-novoe-iskysstvo?source=rubric',
'Любовь нечаянно нагрянет...

Конечно, каждая женщина в душе мечтает, что произойдёт нечто невероятное и перевернёт всю её повседневную, однообразную жизнь. К живущей с мамой 40-летней незамужней Ирине сватается ее начальник Феликс — «маменькин сынок». Сватается он вяленько: третий год ходит в дом, но на предложение руки и сердца даже не намекает. Более того, лелея свои комплексы, приобретённые в детстве, как мужчина он себя никак не проявляет, утверждая, что главной для него является духовная связь. Ирина особых чувств к Феликсу не питает, но, понимая, что замуж выходить и рожать ребёнка давно пора, имитирует заинтересованность и любовь.

В этот вялотекущий роман решает вмешаться мать Ирины, Надежда Андреевна. Переживая за дочь и имея множество претензий к потенциальному зятю, она противопоставляет намерениям Ирины свою житейскую философию. «Муж — это нагрузка к ребёнку, а твой Феликс — это огромная нагрузка!» — говорит она дочери. Но, видя, что та с её мнением не согласна, не по годам энергичная мама решает отбить у «женишка» желание ходить к дочери отчаянным поступком — приводит в однокомнатную квартиру, площадь которой уже оценил живущий с мамой Феликс, «мужчину» — забулдыжку из-под гастронома, представляя его своим женихом.

Тонкий юмор автора, вдохновенная игра актёров. В этом светлом, добром спектакле все ситуации, от смешных и нелепых до грустных и, порой, драматических, выглядят искренне и очень узнаваемо.

В состав исполнителей могут быть внесены изменения без дополнительного уведомления.

Спектакль идет с одним антрактом.',
