('Последняя остановка',
'https://afisha.yandex.ru/samara/theatre_show/posledniaia-ostanovka?source=rubric',
'Сюжет, вполне подходящий для классической пьесы «про любовь», но на деле Ремарк обнажил тяжелое время, когда нацистский режим отживал последние часы. В Берлин вступили советские войска, столкнув между собой жертв и палачей, у которых появилась возможность встать лицом к лицу. Но при этом палачи уже не могли воспользоваться позицией силы, и этот диссонанс создает душераздирающее впечатление. Ремарк не просто описывает события, они лишь декорация к более глобальным вопросам. Человеконенавистничество, агрессивность, способность приспосабливаться и предавать себя — всё это вечные вопросы, которые заставляют задуматься над главными. Способна ли любовь нас спасти? Способно ли прощение всё поправить?

В 1956 году, когда Ремарк работал над романом «Черный обелиск», в перерывах между работой появилась пьеса «Последняя остановка». Хронологически действие пьесы занимает всего два дня 1945 года — 30 апреля и 1 мая.

Пьеса «Последняя остановка» была впервые поставлена в берлинском Ренессанс-театре. Ремарк присутствовал на репетициях и на премьере. Пьесу и по сей день ставят в разных театрах, состоялось несколько показов по телевидению. Теперь такая возможность появилась и у самарских зрителей.',
