'Абсолютно неправдивая история.

Обыкновенная дорога в обыкновенном городе, одностороннее движение, автомобили едут обыкновенной кучей, не соблюдая разделительных полос, дорожных указателей. Жара. Три женщины за рулём, каждая хозяйка в своем авто. Каждая в своей машине поёт, подпевая работающему радио. У каждой своя волна. Все втроём тормозят, так как на дороге пробка...

