('Соглядатай',
'https://afisha.yandex.ru/samara/theatre_show/sogliadatai-gorod?source=rubric',
'Не самый успешный банковский служащий приезжает похоронить свою тётушку и получить наследство, но старушка оказывается чересчур живучей... Зрителям предлагается не только стать соглядатаями чужой жизни, но и поучаствовать в действии...

Канадские критики называют Мориса Панича автором «чёрных комедий, балансирующих на грани между надеждой и отчаянием». Гротесковая пьеса 1995 года «Соглядатай» — почти монодрама о странном существе: немолодом, но гиперактивном банковском служащем Кэмпе, приезжающем в дом своей умирающей тётушки наблюдать за её угасанием. Его затяжные монологи в сторону почти всегда молчащей старушки Грейс — это блеск остроумия, словесная игра, изысканная патологичность, специфическое философское смешение прагматики и наивности, диалог с самим собой, торжество чёрного юмора. Это пьеса о том, как жизнь обманывает наши ожидания.

Одна из самых известных пьес Мориса Панича «Соглядатай» была написана в 1995 году и впервые была поставлена в Виктории (Канада) в театре «Белфрай», получив при этом приз Джесси как лучшая пьеса года. «Соглядатай» с тех пор шёл в более чем тридцати театрах Канады и США. В 2002 года пьеса была показана на престижном Эдинбургском фестивале, а через год состоялась премьера в Лондоне.',
