'Лёгкая и изящная музыкальная комедия с куплетами, танцами, интригой и счастливым финалом. В основе постановки — пьесы русских авторов позапрошлого века: «Хороша и дурна, и глупа, и умна» Ленского и «Свадьба с вензелями» Федорова.

Обе истории завязаны вокруг традиций сватовства русского дворянства. В первой — родители прелестной молодой особы ломают голову, как выдать дочь замуж, когда приданое всего сто душ. Тем временем, возможные жених с невестой успевают сменить взаимную неприязнь на вспыхнувшее чувство.

Во второй — некий помещик мечтает выгодно пристроить замуж свою дочь, но есть одно условие: ее жених должен обязательно иметь инициалы А.Ф., т.к. он уже давно приготовил приданое с этими буквами.',
