'Это спектакль о том, как интимные чувства мужчин и женщин опошляются по их же вине, комедия по рассказам Михаила Зощенко «Аристократка», «Горькая доля» и Аркадия Аверченко «Мужчины», «Жена», «Фат», «Знаток женского сердца». Что, казалось бы , может быть общего у замужней дамы и самодовольного франта, или у аристократки и мужчины-слесаря, из рабочего класса, или у молодой, неопытной девушки и опытного соблазнителя Мастакова — любовь? Может быть, только любовь странная, запретная, несовместимая и разрушительная. Как герои будут преодолевать эти противоречия и что из этого выйдет? Вот об этом и узнает зритель старше 16 лет, которому этот спектакль будет интересен.',
