'Дон Гуан — легендарный литературный образ — символ, который уже стал нарицательным. Обольститель, убийца и великий грешник. Но, что если за этим образом скрывается реальная душа, которая сама понимает, что недостойна счастья и любви.

Александр Сергеевич Пушкин, в своём цикле пьес «Маленькие трагедии», затронул образ Дона Гуана впервые показав, что он может быть человеком, а не просто отрицательным символом. «Каменный гость», это спектакль, где ключевым моментом является обнажение внутренних кошмаров Дона Гуана и его попытки пробиться через них к настоящей, чистой любви. Сможет ли спасти и очистить свою душу великий развратник? Или же они станут его концом?',
