'«Ложь ещё надо придумать, а правда — это так легко...»

Одно креативное агентство сталкивается с труднейшей задачей: спасти многолетнюю ложь, во имя жизни одной бабушки. Её внук живёт вдали от неё и долгие годы пишет ей письма, где он рассказывает о своей успешной и прекрасной жизни. В один день он решает приехать и оказывается, что эти письма писал не он. Неожиданное стечение обстоятельств меняет ход событий, и сама жизнь потребует встречи с реальностью.

Деревья умирают стоя — это испанская пословица, которая говорит о силе человеческого духа, о необходимости уметь скрывать слёзы, даже когда отнята надежда, о достоинстве и чести перед низостью и ложью.

