('Жизель',
'https://afisha.yandex.ru/samara/ballet/zhizel-russkii-moskovskii-balet?source=rubric',
'Балет «Жизель» — в сюжете балета «Жизель» показана нежная и вместе с тем мистическая история о молодой и наивной девушке, которая любит всем сердцем и уверена в ответных чувствах своего избранника Альберта. Но ее поклонник лесничий, открывает обман её возлюбленного, в результате чего она теряет рассудок и умирает, не выдержав предательства.

Теперь Жизель не простая крестьянская девушка, а мстительная и жестокая, как и все виллисы, к которым она присоединяется. Первым, кого они покарали стал Лесничий, пришедший на могилу Жизель. Следующий на это место явился граф Альберт, но душа девушки все еще нежно и преданно любящая его, защищает возлюбленного от мстительных виллис, спасая от гибели. С рассветом исчезают тени всех девушек и самой Жизель, оставляя лишь глубокий след в душе и памяти Альберта, как вечное сожаление о потерянной любви, которая сильнее смерти.

«Русский Московский балет» — успешная труппа классического танца под руководством Михаила Михайлова, в который входят лучшие представители балетных школ России, талантливая перспективная молодежь и зрелые заслуженные мастера танца. Основу балетной труппы на сегодняшний день составляют выпускники Московской академии хореографии, Академии русского балета имени А. Я. Вагановой (Санкт-Петербург) и других известных балетных школ России.',
