('Последняя женщина сеньора Хуана',
'https://afisha.yandex.ru/samara/theatre_show/posledniaia-zhenshchina-senora-khuana?source=rubric',
'Кто не знает легендарного Дона Жуана? Тирсо де Молина, Ж. — Б. Мольер, А. С. Пушкин, Дж. Г. Байрон, Э. Радзинский — авторы, которых интересовала личность Дона Жуана. Гуан, Жуан, Хуан... В пьесе Леонида Жуховицкого его зовут на испанский манер — сеньором Хуаном. А главной темой автор выбирает не любовные похождения испанца, а итог жизни легендарного героя и её осмысление.

Уже не молодой сеньор Хуан ищет тихого пристанища в глухом, Богом забытом, городке. Именно там его настигают брошенная 20 лет назад жена, воин-мститель и загадочный исполнитель. Каждый хочет убить Хуана, и у каждого для этого очень веские причины.

Это спектакль не о зле и губительности страсти, а о стремлении к идеалу любви и добра. Трудно быть счастливым, но если очень сильно захотеть, то всё возможно.

В составе исполнителей возможны изменения без дополнительного уведомления.',
