344),
('Красная Шапочка, или По дороге к бабушке',
'https://afisha.yandex.ru/samara/musical-play/krasnaia-shapochka-ili-po-doroge-k-babushke-samarskii-teatr-gorod?source=rubric',
'Более гуманная и весёлая версия «Красной Шапочки». Вас ждут заразительные песни и неожиданные повороты сюжета.

Спектакль сделан по оригинальному сценарию на основе сказки Шарля Перро.

Девочка, которую зовут Красная Шапочка, отправляется к больной бабушке с корзинкой пирожков. По дороге к бабушке Шапочка встречает в лесу Волка. Мама предупреждала девочку опасаться хищников. Каково было удивление девочки, когда Волк предстаёт вовсе не злым и не страшным хищником, а добрым художником. Волк любит красоту и в лице Красной Шапочки находит долгожданного друга. Ещё девочка встречает Лисию Патрисию и охотника Жака, которые пытаются помешать Красной Шапочке. Но друг Волк-художник помогает девочке преодолеть препятствия.

Герои много поют, танцуют, играют с детьми. Юные зрители помогают добрым героям и мешают дурным. И как в каждой сказке добро перевоспитает зло.',
