('Монах Авель. Мировые хиты от Баха до Пьяццоллы',
'https://afisha.yandex.ru/samara/concert/monakh-avel-mirovye-khity-ot-bakha-do-piatstsolly?source=rubric',
'Фортепианный вечер Монаха Авеля. Вас ждёт музыка разных эпох и стилей. Вы услышите шедевры Баха, Моцарта, Шопена, Рахманинова, а также произведения более современных композиторов — Поля де Сенневиля, Астора Пьяццоллы и других.

Имея профессиональное музыкальное образование, Монах Авель приобрёл известность благодаря своему YouTube-каналу, на который уже подписаны более 355 тысяч человек со всего мира, а многие музыкальные видео набирают сотни тысяч и миллионы просмотров. На данный момент Монах Авель ведёт активную концертную деятельность и выступает на лучших площадках России и за рубежом.

Виртуозная игра Монаха Авеля, несмотря на его внешнюю сдержанность и спокойствие, наполнена множеством эмоций, красок и чувств, что не оставляет слушателей равнодушными. А многогранный репертуар — от Баха и Моцарта до композиций современных композиторов — позволяет каждому найти в его исполнении «свою музыку».

И. С. Бах говорил, что «цель музыки — трогать сердца», и это именно то, что Монаху Авелю удаётся лучше всего.',
