('История игрушек 4',
'https://afisha.yandex.ru/samara/cinema/istoriia-igrashok-4?source=rubric',
'Астронавт Базз, ковбой Вуди, пёс Слинки, тиранозавр Рекс и вся команда игрушек снова вместе, и они как никогда готовы к приключениям. С тех пор, как Энди поступил в колледж, игрушки поселились в доме своей новой хозяйки Бонни, которая вот-вот пойдёт в детский сад. Первый день в детском саду положит начало череде событий, в которой найдётся место и путешествиям с погонями, и знакомству с новыми игрушками, и встречам с некоторыми из старых друзей и даже романтической истории.',
