('Отель',
'https://afisha.yandex.ru/samara/quest/otel-2023?source=rubric',
'Вы получили анонимное приглашение на светский вечер, организованный самыми влиятельными и состоятельными людьми Лондона. Никаких имен, только дата и время. О месте встречи осведомлен только лишь водитель, прибывший за вами. Путь не близкий и хороший сон становится вашим лучшим попутчиком.

Ночь окутывает неизвестный Вам ранее пригород, в который Вы въехали после пробуждения. Однако тайный покровитель решил позаботиться здесь об уютном ночлеге. Персонам Вашего уровня не пристало отдыхать и ужинать в дороге.

Остановившись, вы замечаете Отель, который явно выбивается из общей картины местности: ухоженный и подозрительно располагающий к себе. Должно быть, все уже готово к Вашему заселению. Ведь время не ждет и всего одна ночь отделяет Вас от новой жизни.

Сможете ли вы сегодня хорошенько выспаться и все-таки не опоздать на светский вечер?

Добро пожаловать….Приятного Вам отдыха…

Вас ждет: перформанс с постоянным взаимодействием с игроками; более 120 кв. м игрового пространства; более 8 комнат, каждая из которых имеет свой антураж и уникальность; погружение в атмосферу событий с порога; авторский сюжет, не имеющий аналогов и удерживающий интригу до самого конца; 3 актера, 6 абсолютно разных персонажей с детально проработанными образами; автоматизированная система загадок разного принципа действия, основанных на программировании, отсутствие механических замков; система аудиосводок, записанных профессиональными дикторами; уникальный принцип связи администратора и игроков; световые спецэффекты.

Фотографии игроков: организатор выкладывает в группу «ВКонтакте».
